-- Enable Row Level Security
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.documents enable row level security;

-- Helper function to check editor role
create or replace function public.is_editor(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
  );
$$;

-- Helper function to check membership
create or replace function public.is_member(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

-- Trigger to enforce created_by = auth.uid()
create or replace function public.documents_set_created_by()
returns trigger
language plpgsql
as $$
begin
  new.created_by := auth.uid();
  return new;
end;
$$;

create trigger set_created_by
before insert on public.documents
for each row
execute function public.documents_set_created_by();

-- Policies for teams
create policy "team_select_own" on public.teams
for select
using (public.is_member(id));

-- No insert/update/delete policies for teams (users cannot modify)

-- Policies for team_members
create policy "team_member_select_self" on public.team_members
for select
using (user_id = auth.uid());

-- No insert/update/delete policies for team_members (users cannot modify)

-- Policies for documents
create policy "document_select_visible" on public.documents
for select
using (
  deleted_at IS NULL
  and public.is_member(team_id)
);

create policy "document_insert_editor" on public.documents
for insert
with check (
  public.is_editor(team_id)               -- user must be editor of the target team
  and created_by = auth.uid()             -- creator must be the current user (enforced by trigger)
);

create policy "document_update_editor" on public.documents
for update
using (public.is_editor(team_id))          -- can see rows they are allowed to edit
with check (
  public.is_editor(NEW.team_id)           -- after update, must still be editor of the (new) team
  and (NEW.created_by = created_by)       -- creator cannot be changed
);

create policy "document_delete_creator" on public.documents
for delete
using (created_by = auth.uid());

-- Revoke default privileges and grant appropriate ones
revoke all on public.teams, public.team_members, public.documents from public;
grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

-- Ensure anon role has no privileges (already revoked)
revoke all on public.teams, public.team_members, public.documents from anon;
