-- Policies for teams (R1)
create policy "team_select_self"
    on public.teams
    for select
    using (
        auth.role() = 'authenticated' and
        exists (
            select 1
            from public.team_members tm
            where tm.team_id = teams.id
              and tm.user_id = auth.uid()
        )
    );

-- No insert/update/delete policies for teams (R7) – deny by omission

-- Policies for team_members (R2)
create policy "team_member_self_select"
    on public.team_members
    for select
    using (
        auth.role() = 'authenticated' and
        user_id = auth.uid()
    );

-- No insert/update/delete policies for team_members (R7) – deny by omission

-- Policies for documents (R3, R4, R5, R6)
create policy "document_read"
    on public.documents
    for select
    using (
        auth.role() = 'authenticated' and
        deleted_at is null and
        exists (
            select 1
            from public.team_members tm
            where tm.team_id = documents.team_id
              and tm.user_id = auth.uid()
        )
    );

create policy "document_insert_editor"
    on public.documents
    for insert
    with check (
        auth.role() = 'authenticated' and
        (select role
         from public.team_members tm
         where tm.team_id = NEW.team_id
           and tm.user_id = auth.uid()
        ) = 'editor'
    );

create policy "document_update_editor"
    on public.documents
    for update
    using (
        auth.role() = 'authenticated' and
        (select role
         from public.team_members tm
         where tm.team_id = documents.team_id
           and tm.user_id = auth.uid()
        ) = 'editor'
    )
    with check (
        (select role
         from public.team_members tm
         where tm.team_id = NEW.team_id
           and tm.user_id = auth.uid()
        ) = 'editor'
    );

create policy "document_delete_creator"
    on public.documents
    for delete
    using (
        auth.role() = 'authenticated' and
        created_by = auth.uid()
    );

-- Helper function to enforce creator on INSERT and set created_by
create or replace function public.fn_documents_set_created_by()
returns trigger language plpgsql as $$
begin
    -- enforce authenticated user
    if auth.uid() is null then
        raise exception 'unauthenticated user';
    end if;

    -- set created_by to the current user
    NEW.created_by := auth.uid();

    -- ensure the user is an editor of the target team
    if not exists (
        select 1
        from public.team_members tm
        where tm.team_id = NEW.team_id
          and tm.user_id = auth.uid()
          and tm.role = 'editor'
    ) then
        raise exception 'only editors may create documents for this team';
    end if;

    return NEW;
end;
$$;

-- Trigger for INSERT on documents
create trigger trg_documents_set_created_by
before insert on public.documents
for each row
execute function public.fn_documents_set_created_by();

-- Helper function to enforce editor role on UPDATE
create or replace function public.fn_documents_editor_check()
returns trigger language plpgsql as $$
begin
    if auth.uid() is null then
        raise exception 'unauthenticated user';
    end if;

    -- user must be editor of the (new) team
    if not exists (
        select 1
        from public.team_members tm
        where tm.team_id = NEW.team_id
          and tm.user_id = auth.uid()
          and tm.role = 'editor'
    ) then
        raise exception 'only editors may modify documents for this team';
    end if;

    return NEW;
end;
$$;

-- Trigger for UPDATE on documents
create trigger trg_documents_editor_check
before update on public.documents
for each row
execute function public.fn_documents_editor_check();

-- Revoke any default privileges that could bypass RLS for non‑service roles
revoke all on public.teams from public;
revoke all on public.team_members from public;
revoke all on public.documents from public;

-- Grant SELECT to authenticated role (policies will filter rows)
grant select on public.teams to authenticated;
grant select on public.team_members to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
