-- Enable Row Level Security
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.projects enable row level security;
alter table storage.objects enable row level security;

-- ==========================
-- Helper functions for storage
-- ==========================
create or replace function public.is_project_member(p_uid uuid, p_path text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.projects pr
    join public.org_members om on pr.org_id = om.org_id
    where pr.id = split_part(p_path, '/', 1)::bigint
      and om.user_id = p_uid
  );
$$;

create or replace function public.is_project_admin(p_uid uuid, p_path text)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.projects pr
    join public.org_members om on pr.org_id = om.org_id
    where pr.id = split_part(p_path, '/', 1)::bigint
      and om.user_id = p_uid
      and om.role = 'admin'
  );
$$;

create or replace function public.is_avatar_owner(p_uid uuid, p_path text)
returns boolean
language sql
stable
as $$
  select split_part(p_path, '/', 1) = p_uid::text;
$$;

grant execute on function public.is_project_member(uuid, text) to public;
grant execute on function public.is_project_admin(uuid, text) to public;
grant execute on function public.is_avatar_owner(uuid, text) to public;

-- ==========================
-- Policies for org_members (R1)
-- ==========================
create policy "org_members_select_self_org"
  on public.org_members
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = org_members.org_id
        and om.user_id = auth.uid()
    )
  );

-- No INSERT/UPDATE/DELETE policies -> R6 (only service_role can bypass)

-- ==========================
-- Policies for orgs (R2)
-- ==========================
create policy "orgs_select_member_org"
  on public.orgs
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = orgs.id
        and om.user_id = auth.uid()
    )
  );

-- ==========================
-- Policies for projects (R2, R3)
-- ==========================
create policy "projects_select_member_org"
  on public.projects
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = projects.org_id
