-- Enable Row Level Security on the profiles table
alter table public.profiles enable row level security;

-- R1: Anyone (including anon) can read every profile
create policy "public select profiles"
  on public.profiles
  for select
  using (true);

-- R2 & R5: Only signed‑in users can create a profile, and only for themselves
create policy "authenticated insert own profile"
  on public.profiles
  for insert
  with check (
    auth.role() = 'authenticated'      -- must be a signed‑in user
    and auth.uid() = id                -- profile id must match the user's uid
  );

-- R3 & R5: Users can edit only their own profile; cannot change the owning id
create policy "authenticated update own profile"
  on public.profiles
  for update
  using (
    auth.role() = 'authenticated'      -- must be a signed‑in user
    and auth.uid() = id                -- can only update rows they own
  )
  with check (
    auth.uid() = id                    -- id cannot be changed to another user
  );

-- R4: No delete policy → deletions are denied for all roles (except service_role which bypasses RLS)

-- Grant appropriate privileges to the built‑in roles
grant select on public.profiles to anon;
grant select, insert, update on public.profiles to authenticated;
