-- Enable Row Level Security
alter table public.profiles enable row level security;
alter table public.tickets enable row level security;

-- Helper function to determine if a user is an agent
create or replace function public.is_agent(p_uid uuid)
returns boolean
language sql
stable
as $$
  select coalesce(is_agent, false)
  from public.profiles
  where id = p_uid;
$$;

-- -----------------------------------------------------------------
-- Profiles policies
-- -----------------------------------------------------------------
create policy "profile read (owner or agent)" on public.profiles
  for select
  using (auth.uid() = id or public.is_agent(auth.uid()));

create policy "profile update (owner only)" on public.profiles
  for update
  using (auth.uid() = id)
  with check (auth.uid() = id);

-- Prevent changing the is_agent flag (even by the owner)
create or replace function public.prevent_is_agent_change()
returns trigger
language plpgsql
as $$
begin
  if new.is_agent is distinct from old.is_agent then
    raise exception 'Changing is_agent is not allowed';
  end if;
  return new;
end;
$$;

create trigger trg_prevent_is_agent_change
  before update on public.profiles
  for each row
  execute function public.prevent_is_agent_change();

-- -----------------------------------------------------------------
-- Tickets policies
-- -----------------------------------------------------------------
create policy "ticket read (owner or agent)" on public.tickets
  for select
  using (auth.uid() = requester_id or public.is_agent(auth.uid()));

create policy "ticket insert (customer creates own open ticket)" on public.tickets
  for insert
  with check (
    auth.uid() = requester_id
    and status = 'open'
    and assigned_agent is null
  );

create policy "ticket update (agents only)" on public.tickets
  for update
  using (public.is_agent(auth.uid()));

-- -----------------------------------------------------------------
-- Privilege management
-- -----------------------------------------------------------------
-- Authenticated users get the needed privileges
grant select, insert, update on public.profiles to authenticated;
grant select, insert, update on public.tickets to authenticated;

-- Anonymous users get no privileges
revoke all on public.profiles from anon;
revoke all on public.tickets from anon;
