stable
as $$
  select coalesce(p.is_agent, false)
  from public.profiles p
  where p.id = uid;
$$;

-- ==========================
-- Profiles policies & trigger
-- ==========================

-- R1: Users can read their own profile, agents can read any profile
create policy "profile_select_self_or_agent"
on public.profiles
for select
using (
  auth.uid() = id
  or public.is_agent(auth.uid())
);

-- R2: Users can change only their own display_name; is_agent is immutable
create policy "profile_update_self_display_name"
on public.profiles
for update
using (auth.uid() = id)
with check (
  auth.uid() = id
  and (new.is_agent = old.is_agent)   -- prevent changes to is_agent
);

-- Trigger to enforce immutability of is_agent column (defense‑in‑depth)
create or replace function public.profile_protect_is_agent()
returns trigger
language plpgsql
as $$
begin
  if new.is_agent <> old.is_agent then
    raise exception 'is_agent column is immutable';
  end if;
  return new;
end;
$$;

create trigger protect_is_agent
before update on public.profiles
for each row
execute function public.profile_protect_is_agent();

-- ==========================
-- Tickets policies
-- ==========================

-- R3: Customers read their own tickets; agents read any ticket
create policy "ticket_select_self_or_agent"
on public.tickets
for select
using (
  requester_id = auth.uid()
  or public.is_agent(auth.uid())
);

-- R4: Signed‑in users can open tickets only for themselves, status must be 'open', no assigned agent
create policy "ticket_insert_customer"
on public.tickets
for insert
with check (
  requester_id = auth.uid()
  and status = 'open'
  and assigned_agent is null
);

-- R5: Agents can update any ticket; customers cannot update tickets
create policy "ticket_update_agent"
on public.tickets
for update
using (public.is_agent(auth.uid()))
with check (true);   -- agents may modify any columns

-- R6: No delete policy → deletes are prohibited for all non‑service roles

-- ==========================
-- Privilege management
-- ==========================

-- Ensure anon role has no access (R8)
revoke all on public.profiles from anon, authenticated;
revoke all on public.tickets from anon, authenticated;

-- Grant minimal privileges; RLS will enforce row‑level rules
grant select on public.profiles to authenticated;
grant update (display_name) on public.profiles to authenticated;

grant select, insert, update on public.tickets to authenticated;
