-- Helper function to determine if the current user belongs to HR
create or replace function public.is_hr() returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.employees
    where user_id = auth.uid()
      and department = 'HR'
  );
$$;

-- Policy: employees can read their own row; HR can read any row
create policy employee_select_self_or_hr
  on public.employees
  for select
  using (user_id = auth.uid() or public.is_hr());

-- Policy: only HR can update any employee row
create policy employee_update_hr
  on public.employees
  for update
  using (public.is_hr());

-- Grant necessary privileges to the authenticated role (RLS will filter rows)
grant select, update on public.employees to authenticated;

-- Security‑definer function that returns the directory without salary,
-- bypassing RLS but only for logged‑in employees
create or replace function public.employee_directory_func()
returns table (
  id bigint,
  full_name text,
  department text
)
language sql
security definer
as $$
  -- Disable RLS inside the function
  set local row_security = off;

  -- Ensure the caller is an employee; otherwise return no rows
  if not exists (
    select 1
    from public.employees
    where user_id = auth.uid()
  ) then
    return;
  end if;

  return query
    select e.id, e.full_name, e.department
    from public.employees e;
$$;

-- View exposing the employee directory
create view public.employee_directory as
  select * from public.employee_directory_func();

-- Allow signed‑in employees to read the directory view
grant select on public.employee_directory to authenticated;

-- Ensure anonymous role cannot see the view
revoke all on public.employee_directory from anon;
