  on public.files
  for insert
  to authenticated
  with check (
    owner_id = auth.uid()
    and public.is_not_suspended(auth.uid())
  );

-- Owners can read their own files; shared users can read if share exists and not expired
create policy file_select_owner_or_shared
  on public.files
  for select
  to authenticated
  using (
    public.is_not_suspended(auth.uid()) and (
      owner_id = auth.uid()
      or exists (
        select 1
        from public.file_shares fs
        where fs.file_id = files.id
          and fs.shared_with = auth.uid()
          and (fs.expires_at is null or fs.expires_at > now())
      )
    )
  );

