    on public.expenses
    for update
    using (
        auth.role() = 'authenticated'
        and submitted_by = auth.uid()
        and status = 'pending'
    )
    with check (
        auth.role() = 'authenticated'
        and submitted_by = auth.uid()
        and status = 'pending'
        and decided_by is null
    );

