-- ==========================
-- Helper trigger to forbid status/decided_by changes via UPDATE
-- ==========================
create function public.expenses_prevent_status_change()
returns trigger
language plpgsql
security definer
as $$
begin
    if NEW.status <> OLD.status then
        raise exception 'Status cannot be modified directly';
    end if;
    if NEW.decided_by is distinct from OLD.decided_by then
        raise exception 'decided_by cannot be modified directly';
    end if;
    return NEW;
end;
$$;

create trigger trg_expenses_prevent_status_change
before update on public.expenses
for each row
