-- ==========================
-- decide_expense function (R4, R5)
-- ==========================
create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
as $$
declare
    v_expense public.expenses%rowtype;
    v_is_manager boolean;
begin
    -- fetch the expense row with row‑level security applied (service_role bypasses it)
    select *
    into v_expense
    from public.expenses
    where id = p_expense_id
    for update;

    if v_expense.id is null then
        raise exception 'Expense not found';
    end if;

    if v_expense.status <> 'pending' then
        raise exception 'Only pending expenses can be decided';
    end if;

    if auth.role() = 'service_role' then
        -- service role can decide any pending expense, decided_by stays NULL
        update public.expenses
        set status = case when p_approve then 'approved' else 'rejected' end,
            decided_by = null
        where id = p_expense_id;
        return;
    end if;

    -- regular authenticated user checks
    if v_expense.submitted_by = auth.uid() then
        raise exception 'Submitter cannot decide own expense';
    end if;

    -- is the caller a manager of the expense's department?
    select exists (
        select 1
        from public.department_members dm
        where dm.department_id = v_expense.department_id
          and dm.user_id = auth.uid()
          and dm.is_manager = true
    )
    into v_is_manager;

    if not v_is_manager then
        raise exception 'Only managers of the department can decide this expense';
    end if;

    -- all checks passed – perform the decision
    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = auth.uid()
    where id = p_expense_id;
end;
$$;

