create or replace function public.is_org_owner(p_org_id bigint) returns boolean
language sql stable security definer as $$
  select exists (
    select 1
    from public.org_members
    where org_id = p_org_id
      and user_id = auth.uid()
      and role = 'owner'
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint) returns boolean
language sql stable security definer as $$
  select exists (
    select 1
    from public.org_members
    where org_id = p_org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$;

create or replace function public.org_member_count(p_org_id bigint, p_role text) returns integer
language sql stable security definer as $$
  select count(*)
  from public.org_members
  where org_id = p_org_id
    and role = p_role;
$$;

create or replace function public.can_insert_org_member(p_org_id bigint, p_user_id uuid, p_role text) 
returns boolean language plpgsql stable security definer as $$
declare
  _member_cnt int;
begin
  -- case 1: creator adds themselves as owner when org has no members yet
  if p_user_id = auth.uid() and p_role = 'owner' then
    if exists (select 1 from public.orgs where id = p_org_id and created_by = auth.uid()) then
      select count(*) into _member_cnt
      from public.org_members
      where org_id = p_org_id;
      if _member_cnt = 0 then
        return true;
      end if;
    end if;
  end if;

  -- case 2: owners or admins adding a regular member
  if p_role = 'member' then
    if exists (select 1 from public.org_members
                where org_id = p_org_id
                  and user_id = auth.uid()
                  and role in ('owner','admin')) then
      return true;
    end if;
  end if;

  -- case 3: owners adding an admin or another owner
  if p_role in ('admin','owner') then
    if exists (select 1 from public.org_members
                where org_id = p_org_id
                  and user_id = auth.uid()
                  and role = 'owner') then
      return true;
    end if;
  end if;

  return false;
end;
$$;

--------------------------------------------------------------------
-- Policies for table public.orgs
--------------------------------------------------------------------
-- R1 – any signed‑in user can create an organization; created_by must be themselves
create policy "orgs_insert_self_created"
  on public.orgs
  for insert
  with check (new.created_by = auth.uid());

-- R3 – members (or the creator) can read the organization
create policy "orgs_select_allowed"
  on public.orgs
  for select
  using (
    exists (select 1
            from public.org_members
            where org_id = orgs.id
              and user_id = auth.uid())
    or orgs.created_by = auth.uid()
  );

-- R7 – only owners can rename an organization; other columns immutable
create policy "orgs_update_name_by_owner"
  on public.orgs
  for update
  using (public.is_org_owner(orgs.id))
  with check (
    new.id = old.id
    and new.created_by = old.created_by
    and (new.name = old.name or new.name <> old.name)  -- allow name change, block other changes
  );

-- No delete policy – organizations cannot be deleted through the app

--------------------------------------------------------------------
-- Policies for table public.org_members
--------------------------------------------------------------------
-- R2 & R4 – controlled inserts via helper function
create policy "org_members_insert_allowed"
  on public.org_members
  for insert
  with check (
    public.can_insert_org_member(new.org_id, new.user_id, new.role)
  );

-- R3 – members can see memberships of orgs they belong to
create policy "org_members_select_allowed"
  on public.org_members
  for select
  using (
    exists (select 1
            from public.org_members
            where org_id = org_members.org_id
              and user_id = auth.uid())
  );

-- R4 & R6 – only owners can change a member's role; cannot change own role
create policy "org_members_update_role_by_owner"
  on public.org_members
  for update
  using (public.is_org_owner(org_members.org_id))
  with check (
    new.org_id = old.org_id
    and new.user_id = old.user_id
    and new.role <> old.role               -- role change must happen
    and auth.uid() <> old.user_id          -- cannot change own role
  );

-- R5 – leave organization or owners removing members/admins/owners (with owner‑count guard)
create policy "org_members_delete_allowed"
  on public.org_members
  for delete
  using (
    -- owners can delete any membership row
    public.is_org_owner(org_members.org_id)
    or
    -- a member can delete their own row, unless they are the sole owner
    (auth.uid() = org_members.user_id
     and (
       org_members.role <> 'owner'
       or (public.org_member_count(org_members.org_id, 'owner') > 1)
     )
    )
  );

