-- Revoke public privileges & grant to authenticated role
--------------------------------------------------------------------
revoke all on public.orgs from public;
grant select, insert, update on public.orgs to authenticated;

revoke all on public.org_members from public;
grant select, insert, update, delete on public.org_members to authenticated;
