  from public.org_members
  where org_id = p_org_id and user_id = p_user
  limit 1;
$$;

create or replace function public.can_insert_membership(
    p_user uuid,
    p_org_id bigint,
    p_role text,
    p_target_user uuid
) returns boolean
language plpgsql
security definer
stable as $$
declare
    creator uuid;
    members_cnt int;
    caller_role text;
begin
    -- rule R2: creator can add themselves as owner when org empty
    if p_user = p_target_user then
        select created_by into creator from public.orgs where id = p_org_id;
        select count(*) into members_cnt from public.org_members where org_id = p_org_id;
        if creator = p_user and members_cnt = 0 and p_role = 'owner' then
            return true;
        else
            return false;
        end if;
    end if;

    -- adding other users
    caller_role := public.get_user_role(p_user, p_org_id);
    if caller_role = 'owner' then
        return p_role in ('owner', 'admin', 'member');
    elsif caller_role = 'admin' then
        return p_role = 'member';
    else
        return false;
    end if;
end;
$$;

create or replace function public.can_delete_membership(
    p_user uuid,
    p_org_id bigint,
    p_target_user uuid,
    p_target_role text
) returns boolean
language plpgsql
security definer
stable as $$
declare
    caller_role text;
    owner_cnt int;
begin
    if p_user = p_target_user then
        -- self‑leave (R5)
        if p_target_role <> 'owner' then
            return true;
        else
            select count(*) into owner_cnt
            from public.org_members
            where org_id = p_org_id and role = 'owner';
            return owner_cnt > 1;  -- cannot leave if sole owner
        end if;
    end if;

    -- deleting someone else
    caller_role := public.get_user_role(p_user, p_org_id);
    if caller_role = 'owner' then
        if p_target_role = 'owner' then
            select count(*) into owner_cnt
            from public.org_members
            where org_id = p_org_id and role = 'owner';
            return owner_cnt > 1;  -- cannot delete last owner
        else
            return true;  -- can delete admin or member
        end if;
    elsif caller_role = 'admin' then
        return p_target_role = 'member';  -- admins can only delete members
    else
        return false;
    end if;
end;
$$;

