```sql
-- Enable RLS
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;

-- ==========================
-- Policies for public.orgs
-- ==========================

-- Insert: any signed‑in user can create an org, created_by must be themselves
create policy orgs_insert on public.orgs
  for insert to authenticated
  using (true)
  with check (created_by = auth.uid());

-- Select: creator or any member of the org can view it
create policy orgs_select on public.orgs
  for select to authenticated
  using (
    created_by = auth.uid()
    or exists (
      select 1 from public.org_members m
      where m.org_id = orgs.id and m.user_id = auth.uid()
    )
  );

-- Update: only owners can rename the org (change name); other columns immutable
create policy orgs_update on public.orgs
  for update to authenticated
  using (
    exists (
      select 1 from public.org_members m
      where m.org_id = orgs.id
        and m.user_id = auth.uid()
        and m.role = 'owner'
    )
  )
  with check (
    NEW.id = OLD.id
    and NEW.created_by = OLD.created_by
    and NEW.name is not null
  );

-- Delete: prohibited for normal users (no policy). Service role bypasses RLS.


-- ============================
-- Policies for public.org_members
-- ============================

-- Insert: various allowed scenarios
create policy org_members_insert on public.org_members
  for insert to authenticated
  using (true)
  with check (
    -- creator adds themselves as owner when org empty
    (user_id = auth.uid()
     and role = 'owner'
     and (select created_by from public.orgs o where o.id = org_id) = auth.uid()
     and not exists (select 1 from public.org_members where org_id = org_id))
    or
    -- owners/admins add a member
    (role = 'member'
     and exists (
       select 1 from public.org_members m
       where m.org_id = org_id
         and m.user_id = auth.uid()
         and m.role in ('owner','admin')
     ))
    or
    -- owners add admin or another owner
    (role in ('admin','owner')
     and exists (
       select 1 from public.org_members m
       where m.org_id = org_id
         and m.user_id = auth.uid()
         and m.role = 'owner'
     ))
  );

-- Select: members can see memberships of orgs they belong to
create policy org_members_select on public.org_members
  for select to authenticated
  using (
    exists (
      select 1 from public.org_members m2
      where m2.org_id = org_members.org_id
        and m2.user_id = auth.uid()
    )
  );

-- Update: only owners can change roles of other members; nobody can change their own role
create policy org_members_update on public.org_members
  for update to authenticated
  using (
    exists (
      select 1 from public.org_members m
      where m.org_id = org_members.org_id
        and m.user_id = auth.uid()
        and m.role = 'owner'
    )
    and user_id <> auth.uid()                     -- cannot update own row
  )
  with check (
    NEW.org_id = OLD.org_id
    and NEW.user_id = OLD.user_id
    and NEW.role in ('owner','admin','member')
  );

-- Delete: 
--   * a member can delete own membership (leave) unless they are the sole owner
--   * owners and admins can delete members with role = 'member'
create policy org_members_delete on public.org_members
  for delete to authenticated
  using (
    (
      -- self‑leave (except sole owner)
      user_id = auth.uid()
      and not (
        role = 'owner'
        and (select count(*) from public.org_members m
             where m.org_id = org_members.org_id
               and m.role = 'owner') = 1
      )
    )
    or
    (
      -- owners or admins removing a member
      role = 'member'
      and exists (
        select 1 from public.org_members m
        where m.org_id = org_members.org_id
          and m.user_id = auth.uid()
          and m.role in ('owner','admin')
      )
    )
  );

-- ======================================================
-- Helper: ensure each org always retains at least one owner
-- ======================================================
create or replace function public.ensure_org_owner_exists()
returns trigger language plpgsql as $$
begin
  if TG_OP = 'DELETE' then
    if OLD.role = 'owner' then
      if (select count(*) from public.org_members where org_id = OLD.org_id and role = 'owner') = 1 then
        raise exception 'An organization must have at least one owner';
      end if;
    end if;
    return OLD;
  elsif TG_OP = 'UPDATE' then
    if OLD.role = 'owner' and NEW.role <> 'owner' then
      if (select count(*) from public.org_members where org_id = OLD.org_id and role = 'owner') = 1 then
        raise exception 'An organization must have at least one owner';
      end if;
    end if;
    return NEW;
  end if;
  return NULL;
end;
$$;

create trigger trg_ensure_owner_exists
  before delete or update of role on public.org_members
  for each row execute function public.ensure_org_owner_exists();

-- ======================================================
-- Prevent direct deletion of orgs by normal users
-- (service_role bypasses RLS, so it can still delete if needed)
-- ======================================================
create or replace function public.block_org_deletes()
returns trigger language plpgsql as $$
begin
  raise exception 'Direct deletion of organizations is not allowed through the client API';
  return NULL;
end;
$$;

create trigger trg_block_org_deletes
  before delete on public.orgs
  for each statement execute function public.block_org_deletes();

-- ======================================================
-- Grants
-- ======================================================
grant select, insert, update on public.orgs to authenticated;
grant select, insert, update, delete on public.org_members to authenticated;
