-- Enable row level security
alter table public.finance_staff enable row level security;
alter table public.invoices enable row level security;

-- Helper function to check finance staff membership
create or replace function public.is_finance_staff(p_uid uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.finance_staff fs
    where fs.user_id = p_uid
  );
$$;

-- finance_staff: users can only see their own row
create policy finance_staff_select
  on public.finance_staff
  for select
  using (auth.role() = 'authenticated' and user_id = auth.uid());

-- invoices: read
create policy invoices_select
  on public.invoices
  for select
  using (
    auth.role() = 'authenticated' and
    (created_by = auth.uid() or public.is_finance_staff(auth.uid()))
  );

-- invoices: create (only drafts, creator must be self)
create policy invoices_insert
  on public.invoices
  for insert
  with check (
    auth.role() = 'authenticated' and
    created_by = auth.uid() and
    status = 'draft'
  );

-- invoices: update by creator (while draft)
create policy invoices_update_creator
  on public.invoices
  for update
  using (
    auth.role() = 'authenticated' and
    created_by = auth.uid() and
    status = 'draft'
  )
  with check (
    -- created_by cannot change
    new.created_by = old.created_by
    -- status may stay draft or move to sent, nothing else
    and (
      new.status = old.status
      or (old.status = 'draft' and new.status = 'sent')
    )
    -- if status is not draft, no further changes allowed (handled by using clause)
  );

-- invoices: update by finance staff (sent -> paid/void)
create policy invoices_update_finance
  on public.invoices
  for update
  using (
    auth.role() = 'authenticated' and
    public.is_finance_staff(auth.uid()) and
    old.status = 'sent'
  )
  with check (
    -- only status may change, to paid or void
    new.created_by = old.created_by
    and new.customer = old.customer
    and new.amount = old.amount
    and new.status in ('paid','void')
  );

-- invoices: delete by creator (only drafts)
create policy invoices_delete_creator
  on public.invoices
  for delete
  using (
    auth.role() = 'authenticated' and
    created_by = auth.uid() and
    status = 'draft'
  );

