  if NEW.created_by <> OLD.created_by then
    raise exception 'created_by column is immutable';
  end if;

  -- Identify caller role
  if auth.role() = 'service_role' then
    return NEW;  -- bypass all checks for service_role
  end if;

  -- Creator logic
  if auth.uid() = OLD.created_by then
    -- Allowed only while the invoice is a draft
    if OLD.status <> 'draft' then
      raise exception 'Only draft invoices can be edited by the creator';
    end if;

    -- Status transition allowed: draft -> sent or stay draft
    if NEW.status NOT IN ('draft','sent') then
      raise exception 'Creator may only set status to draft or sent';
    end if;
    if OLD.status = 'draft' and NEW.status = 'sent' then
      -- OK transition
    elsif OLD.status = NEW.status then
      -- staying in same status, ok
    else
      raise exception 'Invalid status transition for creator';
    end if;

    -- Customer and amount may change only while still draft
    if OLD.status = 'draft' then
      -- any change to customer/amount is allowed
      return NEW;
    else
      -- once not draft (should not happen because of above), forbid changes
      if NEW.customer <> OLD.customer or NEW.amount <> OLD.amount then
        raise exception 'Cannot modify customer or amount after draft stage';
      end if;
    end if;

  -- Finance staff logic
  elsif public.is_finance_staff(auth.uid()) then
    -- Only allowed when old status is 'sent'
    if OLD.status <> 'sent' then
      raise exception 'Finance staff can only modify invoices with status sent';
    end if;

    -- Only status change to paid or void allowed
    if NEW.status NOT IN ('paid','void') then
      raise exception 'Finance staff may only change status to paid or void';
    end if;

    -- No other column may be altered
    if NEW.customer <> OLD.customer or NEW.amount <> OLD.amount or NEW.created_by <> OLD.created_by then
      raise exception 'Finance staff may not modify customer, amount, or created_by';
    end if;

    return NEW;

  else
    raise exception 'Unauthorized update attempt';
  end if;
end;
$$;

