-- Enable Row Level Security
alter table public.events enable row level security;
alter table public.delegations enable row level security;

-- Helper functions for delegation checks
create or replace function public.is_valid_delegate(p_delegate uuid, p_owner uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.delegations d
    where d.grantor_id = p_owner
      and d.delegate_id = p_delegate
      and (d.expires_at is null or d.expires_at > now())
  );
$$;

create or replace function public.can_edit_delegate(p_delegate uuid, p_owner uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.delegations d
    where d.grantor_id = p_owner
      and d.delegate_id = p_delegate
      and d.can_edit = true
      and (d.expires_at is null or d.expires_at > now())
  );
$$;

-- -----------------------------------------------------------------
-- EVENTS POLICIES
-- -----------------------------------------------------------------
-- SELECT: owners see all; delegates see non‑private events only
create policy select_events_owner
  on public.events
  for select
  using (owner_id = auth.uid());

create policy select_events_delegate
  on public.events
  for select
  using (
    public.is_valid_delegate(auth.uid(), owner_id)
    and is_private = false
  );

-- INSERT: owners can insert any event; delegates can insert only non‑private events on grantor's calendar
create policy insert_events_owner
  on public.events
  for insert
  with check (owner_id = auth.uid());

create policy insert_events_delegate
  on public.events
  for insert
  using (public.can_edit_delegate(auth.uid(), owner_id))
  with check (
    is_private = false
    and public.is_valid_delegate(auth.uid(), owner_id)
  );

-- UPDATE: owners can edit any; delegates can edit only non‑private events and cannot make them private
create policy update_events_owner
  on public.events
  for update
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy update_events_delegate
  on public.events
  for update
  using (
    public.can_edit_delegate(auth.uid(), owner_id)
    and is_private = false
  )
  with check (
    owner_id = old.owner_id               -- keep owner unchanged (enforced also by trigger)
    and is_private = false                -- never make an event private
  );

-- DELETE: owners can delete any; delegates can delete only non‑private events they can edit
create policy delete_events_owner
  on public.events
  for delete
  using (owner_id = auth.uid());

create policy delete_events_delegate
  on public.events
  for delete
  using (
    public.can_edit_delegate(auth.uid(), owner_id)
    and is_private = false
  );

-- -----------------------------------------------------------------
-- Prevent owner_id from being changed (R2)
-- -----------------------------------------------------------------
create or replace function public.enforce_event_owner_unchanged()
returns trigger
language plpgsql
as $$
begin
  if NEW.owner_id <> OLD.owner_id then
    raise exception 'owner_id cannot be changed';
  end if;
  return NEW;
end;
$$;

create trigger trg_events_owner_unchanged
before update on public.events
for each row
execute function public.enforce_event_owner_unchanged();

-- -----------------------------------------------------------------
-- DELEGATIONS POLICIES
-- -----------------------------------------------------------------
-- SELECT: owners see all delegations they gave; delegates see delegations they received
create policy select_delegations_owner_or_delegate
  on public.delegations
  for select
  using (
    grantor_id = auth.uid()
    or delegate_id = auth.uid()
  );

-- INSERT: only owners can create delegations for their own calendar
create policy insert_delegations_owner
  on public.delegations
  for insert
  with check (grantor_id = auth.uid());

-- UPDATE: only owners can modify their delegations; grantor_id immutable
create policy update_delegations_owner
  on public.delegations
  for update
  using (grantor_id = auth.uid())
  with check (grantor_id = auth.uid());

-- DELETE: only owners can remove their delegations
create policy delete_delegations_owner
  on public.delegations
  for delete
  using (grantor_id = auth.uid());

-- -----------------------------------------------------------------
-- BUSY_SLOTS VIEW (R4)
-- -----------------------------------------------------------------
create or replace view public.busy_slots as
select
  e.owner_id,
  e.starts_at,
  e.ends_at
from public.events e
where
  e.owner_id = auth.uid()
  or exists (
    select 1
    from public.delegations d
    where d.grantor_id = e.owner_id
      and d.delegate_id = auth.uid()
      and (d.expires_at is null or d.expires_at > now())
  );

-- -----------------------------------------------------------------
-- GRANTS / REVOKES
-- -----------------------------------------------------------------
-- Authenticated users get normal DML rights (RLS will filter)
grant select, insert, update, delete on public.events to authenticated;
grant select, insert, update, delete on public.delegations to authenticated;
grant select on public.busy_slots to authenticated;

-- Anonymous users get nothing
revoke all on public.events from anon;
revoke all on public.delegations from anon;
revoke all on public.busy_slots from anon;
