-- Enable Row Level Security
alter table public.conversations enable row level security;
alter table public.participants enable row level security;
alter table public.messages enable row level security;
alter table public.blocks enable row level security;

-- Helper function to check if a user can insert a message into a conversation
create or replace function public.can_insert_message(p_conversation_id bigint, p_sender uuid)
returns boolean
language plpgsql
security definer
as $$
begin
  -- User must be a participant of the conversation
  if not exists (
    select 1
    from public.participants
    where conversation_id = p_conversation_id
      and user_id = p_sender
  ) then
    return false;
  end if;

  -- No other participant may have blocked the sender
  if exists (
    select 1
    from public.participants as part
    join public.blocks as blk
      on blk.blocker_id = part.user_id
     and blk.blocked_id = p_sender
    where part.conversation_id = p_conversation_id
      and part.user_id <> p_sender
  ) then
    return false;
  end if;

  return true;
end;
$$;

-- -------------------------------------------------
-- Conversations
-- -------------------------------------------------
create policy "select own conversations"
  on public.conversations
  for select
  using (
    exists (
      select 1
      from public.participants
      where conversation_id = conversations.id
        and user_id = auth.uid()
    )
  );

-- No insert / update / delete policies → operations denied for authenticated users

-- -------------------------------------------------
-- Participants
-- -------------------------------------------------
create policy "select participants of own conversations"
  on public.participants
  for select
  using (
    exists (
      select 1
      from public.participants as p
      where p.conversation_id = participants.conversation_id
        and p.user_id = auth.uid()
    )
  );

-- -------------------------------------------------
-- Messages
-- -------------------------------------------------
create policy "select messages in own conversations"
  on public.messages
  for select
  using (
    exists (
      select 1
      from public.participants
      where conversation_id = messages.conversation_id
        and user_id = auth.uid()
    )
  );

