  on public.messages
  for insert
  with check (
    auth.uid() = sender_id
    and public.can_insert_message(conversation_id, auth.uid())
  );

create policy "update own message only body"
  on public.messages
  for update
  using (auth.uid() = sender_id)
  with check (
    auth.uid() = sender_id
    and new.conversation_id = old.conversation_id
    and new.sender_id = old.sender_id
  );

create policy "delete own message"
  on public.messages
  for delete
  using (auth.uid() = sender_id);

-- -------------------------------------------------
-- Blocks
