as $$
    select split_part(p_name, '/', 1)::uuid;
$$;

-- Helper function to get the second path segment
create or replace function public.path_second_segment(p_name text)
returns text
language sql
stable
as $$
    select split_part(p_name, '/', 2);
$$;

-- 1️⃣ Public read of any `<user-id>/public/...` object in the `media` bucket
create policy "public_media_read"
    on storage.objects
    for select
    using (
        bucket_id = 'media'
        and public.path_second_segment(name) = 'public'
    );

-- 2️⃣ Authenticated users can read everything inside their own folder (public or private) in `media`
create policy "auth_media_own_read"
    on storage.objects
    for select
    using (
        bucket_id = 'media'
        and public.path_first_segment(name) = auth.uid()
    );

-- 4️⃣ Server‑side code (service_role) can read objects in the `internal` bucket
create policy "service_internal_read"
    on storage.objects
    for select
    using (
        auth.role() = 'service_role'
        and bucket_id = 'internal'
    );

-- 3️⃣ Authenticated users can INSERT objects only under their own folder in `media`
create policy "auth_media_own_insert"
    on storage.objects
    for insert
    with check (
        bucket_id = 'media'
        and public.path_first_segment(name) = auth.uid()
        and owner = auth.uid()
    );

-- 3️⃣ Authenticated users can UPDATE objects only under their own folder in `media`
create policy "auth_media_own_update"
    on storage.objects
    for update
    using (
        bucket_id = 'media'
        and public.path_first_segment(name) = auth.uid()
    )
    with check (
        bucket_id = 'media'
        and public.path_first_segment(name) = auth.uid()
        and owner = auth.uid()
    );

-- 3️⃣ Authenticated users can DELETE objects only under their own folder in `media`
create policy "auth_media_own_delete"
    on storage.objects
    for delete
    using (
        bucket_id = 'media'
        and public.path_first_segment(name) = auth.uid()
    );

-- 4️⃣ Server‑side code (service_role) can manipulate objects in the `internal` bucket
