-- Enable Row Level Security
alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

-- Policies
create policy wallet_self_select on public.wallets
  for select
  using (auth.uid() = user_id);

create policy transfer_self_select on public.transfers
  for select
  using (auth.uid() = from_user or auth.uid() = to_user);

-- No insert / update / delete policies → those actions are denied for non‑service_role users

-- RPC to send points
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
as $$
declare
  v_from uuid := auth.uid();
  v_transfer_id bigint;
begin
  -- authentication & basic validation
  if v_from is null then
    raise exception 'Not authenticated';
  end if;
  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;
  if p_to = v_from then
    raise exception 'Cannot send points to yourself';
  end if;

  -- lock both wallets to avoid race conditions
  perform 1 from public.wallets where user_id = v_from for update;
  perform 1 from public.wallets where user_id = p_to   for update;

  -- existence checks
  if not exists (select 1 from public.wallets where user_id = v_from) then
    raise exception 'Sender wallet not found';
  end if;
  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'Recipient wallet not found';
  end if;

  -- balance check
  if (select balance from public.wallets where user_id = v_from) < p_amount then
    raise exception 'Insufficient balance';
  end if;

  -- perform the transfer atomically
  update public.wallets
    set balance = balance - p_amount
    where user_id = v_from;

  update public.wallets
    set balance = balance + p_amount
    where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount)
    values (v_from, p_to, p_amount)
    returning id into v_transfer_id;

  return v_transfer_id;
end;
$$;

-- Grant execute to regular authenticated users
grant execute on function public.send_points(uuid, integer) to authenticated;
