```sql
-- Enable Row Level Security
alter table public.books enable row level security;
alter table public.librarians enable row level security;
alter table public.loans enable row level security;

-- Helper function: check if a user is a librarian
create or replace function public.is_librarian(p_uid uuid)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.librarians where user_id = p_uid);
$$;

-- Helper function: can a user borrow a given book?
create or replace function public.can_borrow(p_book_id bigint, p_borrower uuid)
returns boolean
language plpgsql
stable
as $$
declare
  v_copies int;
  v_active_book_loans int;
  v_active_user_loans int;
begin
  select copies into v_copies from public.books where id = p_book_id;
  if v_copies is null then
    return false;
  end if;

  select count(*) into v_active_book_loans
  from public.loans
  where book_id = p_book_id and returned_on is null;

  select count(*) into v_active_user_loans
  from public.loans
  where borrower_id = p_borrower and returned_on is null;

  return (v_copies > v_active_book_loans) and (v_active_user_loans < 3);
end;
$$;

-- -------------------------------------------------
-- Books policies
-- -------------------------------------------------
create policy "books_select_authenticated"
  on public.books for select
  using (auth.role() = 'authenticated');

create policy "books_insert_librarian"
  on public.books for insert
  with check (public.is_librarian(auth.uid()));

create policy "books_update_librarian"
  on public.books for update
  with check (public.is_librarian(auth.uid()));

-- -------------------------------------------------
-- Librarians policies (self‑view only)
-- -------------------------------------------------
create policy "librarians_select_self"
  on public.librarians for select
  using (user_id = auth.uid());

-- -------------------------------------------------
-- Loans policies
-- -------------------------------------------------
create policy "loans_select_self_or_librarian"
  on public.loans for select
  using (public.is_librarian(auth.uid()) OR borrower_id = auth.uid());

create policy "loans_insert_borrow"
  on public.loans for insert
  with check (
    borrower_id = auth.uid()
    and public.can_borrow(book_id, auth.uid())
  );

create policy "loans_return_own_active"
  on public.loans for update
  using (borrower_id = auth.uid() and returned_on is null)
  with check (
    new.returned_on is not null
    and new.book_id = old.book_id
    and new.borrower_id = old.borrower_id
    and new.borrowed_on = old.borrowed_on
  );

-- -------------------------------------------------
-- Revoke delete privileges (no delete policies)
-- -------------------------------------------------
revoke delete on public.books from public;
revoke delete on public.loans from public;
revoke delete on public.librarians from public;
