-- Enable Row Level Security on the table
alter table public.push_tokens enable row level security;

-- Revoke default privileges and grant to appropriate roles
revoke all on public.push_tokens from public;
grant select, insert, update, delete on public.push_tokens to authenticated;
grant select, insert, update, delete on public.push_tokens to service_role; -- service_role bypasses RLS

-- SELECT: users can read only their own tokens
create policy "select own push tokens"
    on public.push_tokens
    for select
    using (auth.role() = 'authenticated' and user_id = auth.uid());

-- INSERT: users can insert tokens only for themselves
create policy "insert own push token"
    on public.push_tokens
    for insert
    with check (auth.role() = 'authenticated' and user_id = auth.uid());

-- UPDATE: users can update only their own tokens and cannot change ownership
create policy "update own push token"
    on public.push_tokens
    for update
    using (auth.role() = 'authenticated' and user_id = auth.uid())
    with check (auth.role() = 'authenticated' and user_id = auth.uid());

-- DELETE: users can delete only their own tokens
create policy "delete own push token"
    on public.push_tokens
    for delete
    using (auth.role() = 'authenticated' and user_id = auth.uid());

-- Optional: keep updated_at fresh on insert / update
create or replace function public.fn_push_tokens_set_timestamp()
returns trigger language plpgsql security definer as $$
begin
  NEW.updated_at := now();
  return NEW;
end;
$$;

create trigger trg_push_tokens_timestamp
before insert or update on public.push_tokens
for each row execute function public.fn_push_tokens_set_timestamp();
