  on public.subscriptions
  for select
  to public
  using (
    auth.role() = 'authenticated'
    and lower(email) = lower(coalesce(auth.jwt()->>'email',''))
  );

-- R2 & R5: Authenticated users can delete only their own subscriptions (case‑insensitive email match)
