-- Enable Row Level Security
alter table public.app_config enable row level security;
alter table public.user_flag_overrides enable row level security;

-- Helper function to verify a key is public and user‑overridable
create or replace function public.is_overridable_key(p_key text) 
returns boolean 
language sql 
stable 
as $$
  select coalesce(is_public and user_overridable, false)
  from public.app_config
  where key = p_key;
$$;

-- Policies for app_config
create policy "public read" on public.app_config
  for select
  using (is_public = true or auth.role() = 'service_role');

create policy "service_role write" on public.app_config
  for insert with check (auth.role() = 'service_role')
  using (auth.role() = 'service_role');

create policy "service_role update" on public.app_config
  for update using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "service_role delete" on public.app_config
  for delete using (auth.role() = 'service_role');

-- Policies for user_flag_overrides
create policy "own select" on public.user_flag_overrides
  for select
  using (auth.uid() = user_id);

create policy "own insert" on public.user_flag_overrides
  for insert
  with check (
    auth.uid() = user_id
    and public.is_overridable_key(key)
  );

create policy "own update" on public.user_flag_overrides
  for update
  using (auth.uid() = user_id)
  with check (
    auth.uid() = user_id
    and public.is_overridable_key(key)
  );

create policy "own delete" on public.user_flag_overrides
  for delete
  using (auth.uid() = user_id);

-- Grant execution rights on helper function
grant execute on function public.is_overridable_key(text) to anon, authenticated;

-- Grant table privileges (RLS will enforce row‑level rules)
grant select on public.app_config to anon, authenticated;
grant select, insert, update, delete on public.user_flag_overrides to anon, authenticated;
