-- Enable Row Level Security
alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

-- Helper functions
create or replace function public.is_editor_on_board(p_board_id bigint, p_user uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.board_members bm
    where bm.board_id = p_board_id
      and bm.user_id = p_user
      and bm.role = 'editor'
  );
$$;

create or replace function public.is_board_active(p_board_id bigint)
returns boolean
language sql
stable
as $$
  select not coalesce(
    (select is_archived from public.boards b where b.id = p_board_id),
    true
  );
$$;

-- Boards: members can read their boards; no other actions for non‑service_role
create policy board_select_for_members
on public.boards
for select
using (
  auth.role() = 'authenticated'
  and exists (
    select 1
    from public.board_members bm
    where bm.board_id = boards.id
      and bm.user_id = auth.uid()
  )
);

-- Board members: members can read memberships of boards they belong to
create policy board_members_select_for_board_members
on public.board_members
for select
using (
  auth.role() = 'authenticated'
  and exists (
    select 1
    from public.board_members bm
    where bm.board_id = board_members.board_id
      and bm.user_id = auth.uid()
  )
);

-- Cards: read access for board members
create policy cards_select_for_board_members
on public.cards
for select
using (
  auth.role() = 'authenticated'
  and exists (
    select 1
    from public.board_members bm
    where bm.board_id = cards.board_id
      and bm.user_id = auth.uid()
  )
);

-- Cards: editors can insert on active (non‑archived) boards where they are editors
create policy cards_insert_for_editors
on public.cards
for insert
with check (
  auth.role() = 'authenticated'
  and public.is_editor_on_board(NEW.board_id, auth.uid())
  and public.is_board_active(NEW.board_id)
);

-- Cards: editors can update cards on active boards; new board (if changed) must also satisfy rules
create policy cards_update_for_editors
on public.cards
for update
using (
  auth.role() = 'authenticated'
  and public.is_editor_on_board(cards.board_id, auth.uid())
  and public.is_board_active(cards.board_id)
)
with check (
  public.is_editor_on_board(NEW.board_id, auth.uid())
  and public.is_board_active(NEW.board_id)
);

-- Cards: editors can delete cards on active boards
create policy cards_delete_for_editors
on public.cards
for delete
using (
  auth.role() = 'authenticated'
  and public.is_editor_on_board(cards.board_id, auth.uid())
  and public.is_board_active(cards.board_id)
);
