-- Enable Row Level Security
alter table public.events enable row level security;
alter table public.invites enable row level security;
alter table public.rsvps enable row level security;

-- ==========================
-- EVENTS policies
-- ==========================
create policy events_select on public.events
  for select
  using (
    auth.role() = 'authenticated' and (
      is_private = false
      or host_id = auth.uid()
      or exists (
        select 1 from public.invites i
        where i.event_id = events.id and i.user_id = auth.uid()
      )
    )
  );

create policy events_insert on public.events
  for insert
  with check (
    auth.role() = 'authenticated' and
    auth.uid() = host_id
  );

create policy events_update on public.events
  for update
  using (auth.role() = 'authenticated' and host_id = auth.uid())
  with check (auth.uid() = host_id);  -- prevent host change

create policy events_delete on public.events
  for delete
  using (auth.role() = 'authenticated' and host_id = auth.uid());

-- ==========================
-- INVITES policies
-- ==========================
create policy invites_select on public.invites
  for select
  using (
    auth.role() = 'authenticated' and (
      user_id = auth.uid()
      or exists (
        select 1 from public.events e
        where e.id = invites.event_id and e.host_id = auth.uid()
      )
    )
  );

create policy invites_insert on public.invites
  for insert
  with check (
    auth.role() = 'authenticated' and
    exists (
      select 1 from public.events e
      where e.id = NEW.event_id and e.host_id = auth.uid()
    ) and
    NEW.user_id = NEW.user_id  -- just keep column, host can invite anyone
  );

create policy invites_delete on public.invites
  for delete
  using (
    auth.role() = 'authenticated' and
    exists (
      select 1 from public.events e
      where e.id = invites.event_id and e.host_id = auth.uid()
    )
  );

-- ==========================
-- RSVP capacity check helper
-- ==========================
create or replace function public.check_rsvp_capacity()
returns trigger language plpgsql as $$
begin
  if (select count(*) from public.rsvps where event_id = NEW.event_id) >=
     (select capacity from public.events where id = NEW.event_id) then
    raise exception 'Event capacity reached';
  end if;
  return NEW;
end;
$$;

create trigger rsvps_capacity_check
  before insert on public.rsvps
  for each row execute function public.check_rsvp_capacity();

-- ==========================
-- RSVPS policies
-- ==========================
create policy rsvps_select on public.rsvps
  for select
  using (
    auth.role() = 'authenticated' and (
      exists (
        select 1 from public.events e
        where e.id = rsvps.event_id and e.host_id = auth.uid()
      )
      or exists (
        select 1 from public.rsvps r
        where r.event_id = rsvps.event_id and r.user_id = auth.uid()
      )
    )
  );

create policy rsvps_insert on public.rsvps
  for insert
  with check (
    auth.role() = 'authenticated' and
    NEW.user_id = auth.uid() and
    exists (
      select 1 from public.events e
      where e.id = NEW.event_id and (
        e.is_private = false
        or e.host_id = auth.uid()
        or exists (
          select 1 from public.invites i
          where i.event_id = e.id and i.user_id = auth.uid()
        )
      )
    )
  );

create policy rsvps_delete on public.rsvps
  for delete
  using (
    auth.role() = 'authenticated' and user_id = auth.uid()
  );
