-- Helper function to verify capacity
create or replace function public.can_user_rsvp(p_event_id bigint, p_user_id uuid)
returns boolean
language plpgsql
stable
as $$
declare
  v_capacity int;
  v_current  int;
  v_is_private boolean;
  v_host_id uuid;
begin
  select capacity, is_private, host_id
    into v_capacity, v_is_private, v_host_id
    from public.events
    where id = p_event_id;

  if not found then
    return false;
  end if;

  -- visibility check (same as events_select)
  if v_is_private then
    if p_user_id <> v_host_id
       and not exists (
         select 1
         from public.invites i
         where i.event_id = p_event_id
           and i.user_id = p_user_id
       )
    then
      return false;
    end if;
  end if;

  select count(*) into v_current
    from public.rsvps
    where event_id = p_event_id;

  return v_current < v_capacity;
end;
$$;

-- Trigger to enforce capacity atomically
create or replace function public.rsvp_capacity_check()
returns trigger
language plpgsql
as $$
declare
  v_allowed boolean;
begin
  v_allowed := public.can_user_rsvp(NEW.event_id, NEW.user_id);
  if not v_allowed then
    raise exception 'Cannot RSVP: event is private/not invited or capacity reached';
  end if;
  return NEW;
end;
$$;

create trigger rsvp_capacity_before_insert
  before insert on public.rsvps
  for each row
  execute function public.rsvp_capacity_check();

