      where e.id = rsvps.event_id
        and e.host_id = auth.uid()
    )
    -- or user can see RSVPs of events they have RSVP'd to
    or exists (
      select 1
      from public.rsvps r
      where r.event_id = rsvps.event_id
        and r.user_id = auth.uid()
    )
  );

create policy rsvps_insert on public.rsvps
  for insert
  with check (
    user_id = auth.uid()
    and public.can_user_rsvp(event_id, auth.uid())
  );

create policy rsvps_delete on public.rsvps
  for delete
  using (user_id = auth.uid());

