-- Enable Row Level Security
alter table public.employees enable row level security;
alter table public.leave_requests enable row level security;

-- Revoke default public privileges
revoke all on public.employees from public;
revoke all on public.leave_requests from public;

-- Grant base privileges to authenticated users (service_role bypasses RLS)
grant select on public.employees to authenticated;
grant select, insert, update on public.leave_requests to authenticated;

-- ----------------------------------------------------------------
-- Employees table policies (read‑only directory for signed‑in users)
-- ----------------------------------------------------------------
create policy employee_directory_select
  on public.employees
  for select
  using (auth.role() = 'authenticated');

-- ----------------------------------------------------------------
-- Helper function: is the current user the direct manager of a given employee?
-- ----------------------------------------------------------------
create or replace function public.is_direct_report(p_employee uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.employees e
    where e.manager_id = auth.uid()
      and e.user_id = p_employee
  );
$$;

-- ----------------------------------------------------------------
-- Leave_requests policies
-- ----------------------------------------------------------------

-- 1. Read: self or direct manager
create policy leave_requests_select
  on public.leave_requests
  for select
  using (
    employee_id = auth.uid()
    or public.is_direct_report(employee_id)
  );

-- 2. Insert: employee can only create their own pending request
create policy leave_requests_insert
  on public.leave_requests
  for insert
  with check (
    employee_id = auth.uid()
    and status = 'pending'
    and decided_by is null
  );

-- 3. Update by employee: while pending, may change dates, note or cancel
create policy leave_requests_update_self
  on public.leave_requests
  for update
  using (
    employee_id = auth.uid()
    and status = 'pending'
  )
  with check (
    employee_id = auth.uid()
    and decided_by is null
    and status in ('pending','cancelled')
  );

-- 4. Update by manager: decide (approve/reject) a pending request of a direct report
create policy leave_requests_update_manager
  on public.leave_requests
  for update
  using (
    employee_id in (select user_id from public.employees where manager_id = auth.uid())
    and status = 'pending'
  )
  with check (
    employee_id = old.employee_id
    and starts_on = old.starts_on
    and ends_on = old.ends_on
    and note = old.note
    and status in ('approved','rejected')
    and decided_by = auth.uid()
  );

-- ----------------------------------------------------------------
-- Defensive trigger: ensure employees cannot bypass policies via column tricks
-- (optional but adds an extra safety net)
-- ----------------------------------------------------------------
create or replace function public.prevent_invalid_employee_update()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    -- Employee‑side updates
    if old.employee_id = auth.uid() then
      if old.status <> 'pending' then
        raise exception 'Only pending requests may be modified by the employee';
      end if;
      if new.status not in ('pending','cancelled') then
        raise exception 'Employees may only set status to pending or cancelled';
      end if;
      if new.decided_by is not null then
        raise exception 'Employees cannot set decided_by';
      end if;
    end if;
  end if;
  return new;
end;
$$;

create trigger trg_prevent_invalid_employee_update
  before update on public.leave_requests
  for each row
  execute function public.prevent_invalid_employee_update();
