    and (new.status = status or new.status = 'cancelled')
    and new.decided_by is null
    -- dates and note may change, other columns must stay unchanged
    and new.starts_on is not distinct from starts_on
    and new.ends_on   is not distinct from ends_on
    and new.note      is not distinct from note
  );

