```sql
-- Enable RLS on tables
alter table public.employees enable row level security;
alter table public.leave_requests enable row level security;

-- -------------- Employees table --------------
-- Employees (directory) can be read by any authenticated user
create policy employee_select on public.employees
  for select
  using (auth.role() = 'authenticated');

-- No inserts/updates/deletes allowed via the app
-- (no corresponding policies, so they are denied)

grant select on public.employees to authenticated;

-- -------------- Leave Requests table --------------
-- 1. SELECT: employee sees own requests; manager sees direct reports' requests
create policy leave_requests_select on public.leave_requests
  for select
  using (
    employee_id = auth.uid()
    or exists (
      select 1
      from public.employees e
      where e.user_id = leave_requests.employee_id
        and e.manager_id = auth.uid()
    )
  );

-- 2. INSERT: employees can only create requests for themselves
create policy leave_requests_insert on public.leave_requests
  for insert
  with check (employee_id = auth.uid());

-- 3. UPDATE: allow updates while request is pending; detailed checks enforced by trigger
create policy leave_requests_update on public.leave_requests
  for update
  using (
    status = 'pending'
    and (
      employee_id = auth.uid()
      or exists (
        select 1
        from public.employees e
        where e.user_id = leave_requests.employee_id
          and e.manager_id = auth.uid()
      )
    )
  )
  with check (true);  -- actual column‑level rules are in the trigger

-- No DELETE policy → deletes are prohibited

grant select, insert, update on public.leave_requests to authenticated;

-- -------------- Trigger to enforce business rules --------------
create or replace function public.enforce_leave_requests_update()
returns trigger language plpgsql as $$
begin
  -- Once a request is not pending, no further changes are allowed
  if OLD.status <> 'pending' then
    raise exception 'Only pending requests can be modified';
  end if;

  -- Ensure employee_id never changes
  if NEW.employee_id <> OLD.employee_id then
    raise exception 'employee_id cannot be changed';
  end if;

  -- Determine if the caller is the employee
  if auth.uid() = OLD.employee_id then
    -- Employee may modify dates, note, or cancel the request
    if NEW.status not in ('pending','cancelled') then
      raise exception 'Employees may only set status to pending or cancelled';
    end if;
    if NEW.decided_by is not null then
      raise exception 'Employees cannot set decided_by';
    end if;
    -- Dates and note may change freely; nothing else to check
    return NEW;
  end if;

  -- Determine if the caller is the direct manager
  if exists (
        select 1
        from public.employees e
        where e.user_id = OLD.employee_id
          and e.manager_id = auth.uid()
      ) then
    -- Manager may only approve or reject; cannot alter dates, note or cancel
    if NEW.status not in ('approved','rejected') then
      raise exception 'Managers may only set status to approved or rejected';
    end if;
    if NEW.decided_by <> auth.uid() then
      raise exception 'decided_by must be the manager performing the action';
    end if;
    if NEW.starts_on <> OLD.starts_on
       or NEW.ends_on <> OLD.ends_on
       or (NEW.note is distinct from OLD.note) then
      raise exception 'Managers cannot modify dates or note';
    end if;
    return NEW;
  end if;

  raise exception 'User is neither the employee nor its direct manager';
end;
