-- Enable RLS
alter table public.employees enable row level security;
alter table public.leave_requests enable row level security;

-- -------------------------------------------------
-- Employees table policies
-- -------------------------------------------------
-- Employees (directory) can be read by any authenticated user
create policy employees_select
  on public.employees
  for select
  using (auth.role() = 'authenticated');

-- No inserts/updates/deletes for non‑service_role users
create policy employees_no_dml
  on public.employees
  for all
  using (false);

-- -------------------------------------------------
-- Leave_requests table policies
-- -------------------------------------------------
-- Read: employee themselves or their direct manager
create policy leave_requests_select
  on public.leave_requests
  for select
  using (
    employee_id = auth.uid()
    or exists (
      select 1
      from public.employees e
      where e.user_id = employee_id
        and e.manager_id = auth.uid()
    )
  );

-- Insert: only for self, status must be pending, decided_by must be null
create policy leave_requests_insert
  on public.leave_requests
  for insert
  with check (
    employee_id = auth.uid()
    and coalesce(decided_by, auth.uid()) = auth.uid()  -- decided_by must be null (or auth.uid() which is impossible)
    and status = 'pending'
  );

-- Update: allowed for employee (pending) or manager (pending)
create policy leave_requests_update
  on public.leave_requests
  for update
  using (
    employee_id = auth.uid()
    or exists (
      select 1
      from public.employees e
      where e.user_id = employee_id
        and e.manager_id = auth.uid()
    )
  )
  with check (true);  -- actual column‑level enforcement done in trigger

-- -------------------------------------------------
-- Trigger function enforcing business rules on UPDATE
-- -------------------------------------------------
create or replace function public.leave_requests_update_enforcer()
returns trigger
language plpgsql
security definer
as $$
declare
    is_manager boolean;
begin
    -- Disallow any change once the request is no longer pending
    if old.status <> 'pending' then
        raise exception 'Cannot modify a leave request that is not pending';
    end if;

    -- Employee‑side updates
    if auth.uid() = old.employee_id then
        -- employee may only change dates, note, or cancel (status = cancelled)
        if new.employee_id <> old.employee_id then
            raise exception 'Employee cannot change employee_id';
        end if;
        if new.decided_by is not null and new.decided_by <> old.decided_by then
            raise exception 'Employee cannot set decided_by';
        end if;
        if new.status not in ('pending','cancelled') then
            raise exception 'Employee may only keep status pending or set it to cancelled';
        end if;
        -- ensure no other columns are altered
        if new.starts_on is distinct from old.starts_on
           or new.ends_on is distinct from old.ends_on
           or new.note is distinct from old.note
           or new.status is distinct from old.status then
            return new;  -- allowed changes
        else
            raise exception 'No permitted changes detected for employee';
        end if;
    end if;

    -- Manager‑side updates
    select exists (
        select 1
        from public.employees e
        where e.user_id = old.employee_id
          and e.manager_id = auth.uid()
    ) into is_manager;

    if is_manager then
        -- manager may only set status to approved/rejected and record themselves
        if new.status not in ('approved','rejected') then
            raise exception 'Manager may only set status to approved or rejected';
        end if;
        if new.decided_by <> auth.uid() then
            raise exception 'Manager must set decided_by to their own user id';
        end if;
        -- ensure no other fields change
        if new.employee_id <> old.employee_id
           or new.starts_on is distinct from old.starts_on
           or new.ends_on is distinct from old.ends_on
           or new.note is distinct from old.note
           or new.decided_by is distinct from old.decided_by then
            raise exception 'Manager may only change status and decided_by';
        end if;
        return new;
    end if;

    raise exception 'User not authorized to update this leave request';
end;
$$;

create trigger trg_leave_requests_update_enforcer
  before update on public.leave_requests
  for each row
  execute function public.leave_requests_update_enforcer();

