-- Enable Row Level Security
alter table public.products enable row level security;
alter table public.purchases enable row level security;
alter table public.reviews enable row level security;

-- ------------------------------------------------------------------
-- Policies for public.products (readable by anyone)
create policy "public read products"
  on public.products
  for select
  using (true);

-- Policies for public.purchases (users see only their own rows)
create policy "authenticated select own purchases"
  on public.purchases
  for select
  using (auth.role() = 'authenticated' and auth.uid() = user_id);

-- ------------------------------------------------------------------
-- Policies for public.reviews
-- Public read
create policy "public read reviews"
  on public.reviews
  for select
  using (true);

-- Insert: authenticated users, only their own user_id, only for products they purchased
create policy "authenticated insert own review"
  on public.reviews
  for insert
  with check (
    auth.role() = 'authenticated' and
    auth.uid() = user_id and
    exists (
      select 1
      from public.purchases p
      where p.user_id = auth.uid()
        and p.product_id = NEW.product_id
    )
  );

-- Update: only the owner may update
create policy "authenticated update own review"
  on public.reviews
  for update
  using (auth.role() = 'authenticated' and auth.uid() = user_id);

-- Delete: only the owner may delete
create policy "authenticated delete own review"
  on public.reviews
  for delete
  using (auth.role() = 'authenticated' and auth.uid() = user_id);

-- ------------------------------------------------------------------
-- Helper function to protect is_featured and enforce ownership on non‑service_role writes
create or replace function public.reviews_user_protect()
returns trigger
language plpgsql
as $$
begin
  -- Service role bypasses all checks
  if auth.role() <> 'service_role' then
    -- Force ownership
    new.user_id := auth.uid();

    -- Users may never set or change is_featured
    new.is_featured := false;

    -- Prevent changing immutable columns on update
    if tg_op = 'UPDATE' then
      if new.product_id <> old.product_id then
        raise exception 'product_id cannot be changed';
      end if;
      if new.user_id <> old.user_id then
        raise exception 'user_id cannot be changed';
      end if;
    end if;
  end if;
  return new;
end;
$$;

-- Trigger to invoke the protection function
create trigger reviews_user_protect
before insert or update on public.reviews
for each row execute function public.reviews_user_protect();

-- ------------------------------------------------------------------
-- Grants (service_role already has full access)
grant select on public.products to anon, authenticated;
grant select on public.reviews to anon, authenticated;
grant select, insert, update, delete on public.reviews to authenticated;
grant select on public.purchases to authenticated;
