returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.purchases
    where user_id = p_user
      and product_id = p_product
  );
$$;

-- Trigger: enforce that non‑service_role users cannot set is_featured
create or replace function public.enforce_review_featured()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() <> 'service_role' then
    new.is_featured := false;
  end if;
  return new;
end;
$$;

create trigger trg_enforce_review_featured
before insert or update on public.reviews
for each row execute function public.enforce_review_featured();

-- Policies

-- R1: anyone can read products
create policy "public read products"
on public.products
for select
using (true);

-- R2: users see only their own purchases
create policy "user can view own purchases"
on public.purchases
for select
using (auth.uid() = user_id);

-- R1: anyone can read reviews
create policy "public read reviews"
on public.reviews
for select
using (true);

-- R3: authenticated users can insert a review only for purchased products,
-- cannot set is_featured
create policy "authenticated insert reviews"
on public.reviews
for insert
to authenticated
using (auth.uid() is not null)
with check (
  auth.uid() = user_id
  and public.can_review(user_id, product_id)
  and new.is_featured = false
);

-- R3: authenticated users can update their own reviews, but not is_featured
create policy "authenticated update reviews"
on public.reviews
for update
to authenticated
using (auth.uid() = user_id)
with check (
  auth.uid() = user_id
  and public.can_review(user_id, product_id)
  and new.is_featured = old.is_featured
);

-- R3: authenticated users can delete their own reviews
create policy "authenticated delete reviews"
on public.reviews
for delete
to authenticated
using (auth.uid() = user_id);

-- Grants

grant usage on schema public to anon, authenticated;

grant select on public.products to anon, authenticated;
grant select on public.reviews to anon, authenticated;
grant select on public.purchases to authenticated;

grant select, insert, update, delete on public.reviews to authenticated;
