-- Enable Row Level Security
alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

-- Helper function to check staff membership
create or replace function public.is_staff(p_restaurant_id bigint)
returns boolean
stable
language sql
as $$
  select exists (
    select 1
    from public.restaurant_staff rs
    where rs.restaurant_id = p_restaurant_id
      and rs.user_id = auth.uid()
  );
$$;

-- Policies for restaurants
create policy "restaurants select for authenticated"
  on public.restaurants
  for select
  using (auth.role() = 'authenticated');

-- Policies for restaurant_staff (read‑only)
create policy "staff select for authenticated"
  on public.restaurant_staff
  for select
  using (auth.role() = 'authenticated');

-- Policies for reservations
create policy "reservations select own or staff"
  on public.reservations
  for select
  using (
    user_id = auth.uid()
    or public.is_staff(restaurant_id)
  );

create policy "guest insert reservation"
  on public.reservations
  for insert
  with check (
    user_id = auth.uid()
    and reserved_for > now()
    and status = 'booked'
  );

create policy "guest cancel reservation"
  on public.reservations
  for update
  using (
    user_id = auth.uid()
    and status = 'booked'
    and reserved_for > now()
  )
  with check (
    status = 'cancelled'
    and user_id = auth.uid()
    and restaurant_id = old.restaurant_id
    and party_size = old.party_size
    and reserved_for = old.reserved_for
  );

create policy "staff update reservation status"
  on public.reservations
  for update
  using (
    public.is_staff(restaurant_id)
    and status = 'booked'
    and reserved_for <= now()
  )
  with check (
    (status = 'seated' or status = 'no_show')
    and restaurant_id = old.restaurant_id
    and user_id = old.user_id
    and party_size = old.party_size
    and reserved_for = old.reserved_for
  );

-- Revoke any default privileges from anonymous users
revoke all on public.restaurants from anon;
revoke all on public.restaurant_staff from anon;
revoke all on public.reservations from anon;

-- Grant needed privileges to authenticated users
grant usage on schema public to authenticated;
grant select on public.restaurants to authenticated;
grant select on public.restaurant_staff to authenticated;
grant select, insert, update on public.reservations to authenticated;
