revoke all on public.surveys from public;
revoke all on public.survey_responses from public;

-- Grant needed privileges to the authenticated role
grant select, insert, update on public.surveys to authenticated;
grant select, insert, update on public.survey_responses to authenticated;

-- Helper function for aggregated survey results (security definer)
create or replace function public.get_survey_results()
returns table (
  survey_id bigint,
  responses integer,
  avg_score numeric
) language sql security definer
as $$
  select
    s.id as survey_id,
    count(r.respondent_id) as responses,
    round(avg(r.score)::numeric, 2) as avg_score
  from public.surveys s
  join public.survey_responses r on r.survey_id = s.id
  group by s.id
  having count(r.respondent_id) >= 3
    and (
      auth.role() = 'service_role'
      or s.owner_id = auth.uid()
    );
$$;

-- Grant execute on the helper function
grant execute on function public.get_survey_results() to authenticated;
grant execute on function public.get_survey_results() to service_role;

-- View exposing survey results
create view public.survey_results as
select * from public.get_survey_results();

-- Grant select on the view
grant select on public.survey_results to authenticated;
grant select on public.survey_results to service_role;
