-- Enable Row Level Security
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.invites enable row level security;

-- Policies for orgs
create policy orgs_select on public.orgs
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = orgs.id
        and om.user_id = auth.uid()
    )
  );

-- Policies for org_members
create policy org_members_select on public.org_members
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = org_members.org_id
        and om.user_id = auth.uid()
    )
  );

-- Policies for invites
create policy invites_select on public.invites
  for select
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = invites.org_id
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

create policy invites_insert on public.invites
  for insert
  with check (
    invited_by = auth.uid()
    and exists (
      select 1
      from public.org_members om
      where om.org_id = invites.org_id
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

create policy invites_delete on public.invites
  for delete
  using (
    exists (
      select 1
      from public.org_members om
      where om.org_id = invites.org_id
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

-- Function to accept an invite
create or replace function public.accept_invite(p_token text)
returns bigint
language plpgsql
security definer
as $$
declare
    v_invite public.invites%rowtype;
    v_user_id uuid := auth.uid();
    v_user_email text;
begin
    -- must be authenticated
    if v_user_id is null then
        raise exception 'unauthenticated';
    end if;

    -- extract verified email from JWT (case‑insensitive)
    v_user_email := lower((auth.jwt() ->> 'email'));
    if v_user_email is null then
        raise exception 'email claim missing in JWT';
    end if;

    -- lock the invite row
    select *
    into v_invite
    from public.invites
    where token = p_token
    for update;

    if not found then
        raise exception 'invalid invite token';
    end if;

    if v_invite.expires_at <= now() then
        raise exception 'invite has expired';
    end if;

    if v_invite.accepted_at is not null then
        raise exception 'invite already accepted';
    end if;

    if lower(v_invite.email) <> v_user_email then
        raise exception 'invite email does not match authenticated user';
    end if;

    -- add membership
    insert into public.org_members (org_id, user_id, role)
    values (v_invite.org_id, v_user_id, v_invite.role);

    -- mark invite as accepted
    update public.invites
    set accepted_at = now()
    where token = p_token;

    return v_invite.org_id;
end;
$$;

-- Grant execute on the RPC to authenticated users
grant execute on function public.accept_invite(text) to authenticated;
```

