alter table public.ride_bookings enable row level security;

-- ========= Rides policies (R1) =========
-- Any signed‑in user can read rides
create policy rides_select on public.rides
  for select
  using (auth.role() = 'authenticated');

-- Drivers can insert rides as themselves
create policy rides_insert on public.rides
  for insert
  with check (auth.role() = 'authenticated' and driver_id = auth.uid());

-- Drivers can update only their own rides
create policy rides_update on public.rides
  for update
  using (auth.role() = 'authenticated' and driver_id = auth.uid())
  with check (driver_id = auth.uid());

-- Drivers can delete only their own rides
create policy rides_delete on public.rides
  for delete
  using (auth.role() = 'authenticated' and driver_id = auth.uid());

-- ========= Ride Bookings policies (R2‑R4) =========
-- Helper: can the ride accept another confirmed booking?
create or replace function public.can_confirm(p_ride_id bigint)
returns boolean
language plpgsql
security definer
stable
as $$
declare
    v_seats int;
    v_confirmed int;
begin
    select seats, 
           (select count(*) from public.ride_bookings where ride_id = p_ride_id and status = 'confirmed')
    into v_seats, v_confirmed
    from public.rides
    where id = p_ride_id;

    return v_seats > v_confirmed;
end;
$$;

-- Passengers see their own bookings; drivers see bookings on rides they drive
create policy bookings_select on public.ride_bookings
  for select
  using (
    auth.role() = 'authenticated' and
    ( passenger_id = auth.uid()
      or exists (
          select 1
          from public.rides r
          where r.id = ride_bookings.ride_id
            and r.driver_id = auth.uid()
      )
    )
  );

-- Passengers can request a seat (R3)
create policy bookings_insert on public.ride_bookings
  for insert
  with check (
    auth.role() = 'authenticated'
    and passenger_id = auth.uid()
    and not exists (
        select 1
        from public.rides r
        where r.id = ride_id
          and r.driver_id = auth.uid()          -- cannot book own ride
    )
    and (select departs_at from public.rides where id = ride_id) > now()
  );

-- Passengers can withdraw their own booking before departure (R3)
create policy bookings_delete on public.ride_bookings
  for delete
  using (
    auth.role() = 'authenticated'
    and passenger_id = auth.uid()
    and (select departs_at from public.rides where id = ride_id) > now()
  );

-- Drivers can update status only (confirm/decline) before departure and respecting capacity (R4)
create policy bookings_update_status on public.ride_bookings
  for update
  using (
    auth.role() = 'authenticated'
    and exists (
        select 1
        from public.rides r
        where r.id = ride_bookings.ride_id
          and r.driver_id = auth.uid()
    )
    and (select departs_at from public.rides where id = ride_id) > now()
  )
  with check (
    new.status in ('confirmed','declined')
    and (
        new.status = 'declined'
        or (new.status = 'confirmed' and public.can_confirm(ride_id))
    )
    -- prohibit changes to any column other than status
    and new.passenger_id = old.passenger_id
    and new.ride_id = old.ride_id
    and coalesce(new.status, '') = coalesce(old.status, '')
        or new.status <> old.status
  );

-- Trigger to guarantee only status may be changed (defense in depth)
create or replace function public.enforce_booking_immutable()
returns trigger
language plpgsql
security definer
as $$
begin
    if (new.ride_id <> old.ride_id) or (new.passenger_id <> old.passenger_id) then
        raise exception 'Only the status column may be updated on ride_bookings';
    end if;
    return new;
end;
$$;

create trigger trg_enforce_booking_immutable
before update on public.ride_bookings
for each row
execute function public.enforce_booking_immutable();

-- ========= Grants (R5 & R6) =========
revoke all on public.rides from public;
revoke all on public.ride_bookings from public;

grant select, insert, update, delete on public.rides to authenticated;
grant select, insert, update, delete on public.ride_bookings to authenticated;

-- Service role already bypasses RLS; no extra grants needed
