-- Enable Row Level Security
alter table public.locations enable row level security;
alter table public.location_staff enable row level security;
alter table public.stock enable row level security;

-- Helper functions
create or replace function public.is_auditor() returns boolean
language sql immutable
as $$
  select coalesce(auth.jwt() -> 'app_metadata' ->> 'role' = 'auditor', false);
$$;

create or replace function public.is_staff_of(p_location_id bigint) returns boolean
language sql immutable
as $$
  select exists (
    select 1
    from public.location_staff ls
    where ls.location_id = p_location_id
      and ls.user_id = auth.uid()
  );
$$;

create or replace function public.location_is_frozen(p_location_id bigint) returns boolean
language sql immutable
as $$
  select coalesce(
    (select l.is_frozen from public.locations l where l.id = p_location_id),
    true
  );
$$;

-- Policies for locations (read‑only for authenticated users)
create policy "locations_select_authenticated"
  on public.locations
  for select
  using (auth.uid() is not null);

-- Policies for location_staff
create policy "location_staff_select_staff"
  on public.location_staff
  for select
  using (
    public.is_staff_of(location_id)
    or public.is_auditor()
  );

-- No insert/update/delete policies on location_staff (read‑only)

-- Policies for stock
-- SELECT: staff see their locations, auditors see all
create policy "stock_select"
  on public.stock
  for select
  using (
    public.is_staff_of(location_id)
    or public.is_auditor()
  );

-- INSERT: only staff of the target location, location not frozen, auditors prohibited
create policy "stock_insert"
  on public.stock
  for insert
  with check (
    public.is_staff_of(location_id)
    and not public.location_is_frozen(location_id)
    and not public.is_auditor()
  );

-- UPDATE: must be staff of original row, cannot move to non‑staff location,
-- location (new) not frozen, auditors prohibited
create policy "stock_update"
  on public.stock
  for update
  using (
    public.is_staff_of(location_id)
    and not public.location_is_frozen(location_id)
    and not public.is_auditor()
  )
  with check (
    public.is_staff_of(new.location_id)
    and not public.location_is_frozen(new.location_id)
    and not public.is_auditor()
  );

-- DELETE: only staff of the row's location, location not frozen, auditors prohibited
create policy "stock_delete"
  on public.stock
  for delete
  using (
    public.is_staff_of(location_id)
    and not public.location_is_frozen(location_id)
    and not public.is_auditor()
  );

-- Grants (service_role bypasses RLS automatically)
grant select on public.locations to authenticated;
grant select, insert, update, delete on public.stock to authenticated;
grant select on public.location_staff to authenticated;

revoke all on public.locations from anon;
revoke all on public.stock from anon;
revoke all on public.location_staff from anon;
