```sql
-- Enable RLS on all tables
alter table public.folders enable row level security;
alter table public.folder_grants enable row level security;
alter table public.documents enable row level security;

-- Helper: check ownership (or ancestor ownership)
create or replace function public.is_owner_or_ancestor(p_folder_id bigint, p_user uuid)
returns boolean language sql stable as $$
  with recursive ancestors as (
    select id, owner_id, parent_id
    from public.folders
    where id = p_folder_id
    union all
    select f.id, f.owner_id, f.parent_id
    from public.folders f
    join ancestors a on f.id = a.parent_id
  )
  select exists (select 1 from ancestors where owner_id = p_user);
$$;

-- Helper: check grant (or ancestor grant)
create or replace function public.has_grant_or_ancestor(p_folder_id bigint, p_user uuid, p_edit boolean)
returns boolean language sql stable as $$
  with recursive ancestors as (
    select id, parent_id
    from public.folders
    where id = p_folder_id
    union all
    select f.id, f.parent_id
    from public.folders f
    join ancestors a on f.id = a.parent_id
  )
  select exists (
    select 1
    from ancestors a
    join public.folder_grants g on g.folder_id = a.id
    where g.user_id = p_user
      and (p_edit = false or g.can_edit = true)
  );
$$;

--------------------------------------------------------------------
-- FOLDERS
--------------------------------------------------------------------
-- SELECT (read) policy
create policy folder_select on public.folders
  for select
  using (
    auth.role() = 'authenticated' and
    ( public.is_owner_or_ancestor(id, auth.uid())
      or public.has_grant_or_ancestor(id, auth.uid(), false) )
  );

-- INSERT (create) policy
create policy folder_insert on public.folders
  for insert
  with check (
    auth.role() = 'authenticated' and
    owner_id = auth.uid() and
    (
      parent_id is null
      or public.is_owner_or_ancestor(parent_id, auth.uid())
      or public.has_grant_or_ancestor(parent_id, auth.uid(), false)
    )
  );

-- UPDATE (rename / move) policy – only owners/ancestors may modify
create policy folder_update on public.folders
  for update
  using (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(id, auth.uid())
  )
  with check (
    auth.role() = 'authenticated' and
    owner_id = auth.uid() and
    (
      parent_id is null
      or public.is_owner_or_ancestor(parent_id, auth.uid())
      or public.has_grant_or_ancestor(parent_id, auth.uid(), false)
    )
  );

-- DELETE policy – only owners/ancestors may delete
create policy folder_delete on public.folders
  for delete
  using (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(id, auth.uid())
  );

--------------------------------------------------------------------
-- FOLDER_GRANTS
--------------------------------------------------------------------
-- SELECT policy – users can see their own grants and grants on folders they own/ancestor‑own
create policy folder_grant_select on public.folder_grants
  for select
  using (
    auth.role() = 'authenticated' and
    ( user_id = auth.uid()
      or public.is_owner_or_ancestor(folder_id, auth.uid()) )
  );

-- INSERT / UPDATE / DELETE – only owners/ancestors of the folder may manage grants
create policy folder_grant_modify on public.folder_grants
  for insert
  with check (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(folder_id, auth.uid())
  );

create policy folder_grant_modify_upd on public.folder_grants
  for update
  using (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(folder_id, auth.uid())
  )
  with check (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(folder_id, auth.uid())
  );

create policy folder_grant_modify_del on public.folder_grants
  for delete
  using (
    auth.role() = 'authenticated' and
    public.is_owner_or_ancestor(folder_id, auth.uid())
  );

--------------------------------------------------------------------
-- DOCUMENTS
--------------------------------------------------------------------
-- SELECT policy – read if owner/ancestor or read grant
create policy document_select on public.documents
  for select
  using (
