-- RPC to approve a request
create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_req   public.access_requests%rowtype;
    v_is_ops boolean;
    v_already boolean;
    v_cnt   int;
begin
    -- must be an authenticated user
    if auth.uid() is null then
        raise exception 'unauthenticated';
    end if;

    -- caller must be on the ops team
    select true into v_is_ops
    from public.ops_team ot
    where ot.user_id = auth.uid()
    limit 1;

    if not found then
        raise exception 'caller is not a member of the ops team';
    end if;

    -- fetch the request and lock it
    select *
    into v_req
    from public.access_requests ar
    where ar.id = p_request_id
    for update;

    if not found then
        raise exception 'request % does not exist', p_request_id;
    end if;

    if v_req.status <> 'pending' then
        raise exception 'request % is not pending', p_request_id;
    end if;

    if v_req.requester_id = auth.uid() then
        raise exception 'requester cannot approve own request';
    end if;

    -- ensure caller has not already approved
    select true into v_already
    from public.access_approvals aa
    where aa.request_id = p_request_id
      and aa.approver_id = auth.uid()
    limit 1;

    if found then
        raise exception 'caller has already approved request %', p_request_id;
    end if;

    -- record the approval
    insert into public.access_approvals (request_id, approver_id, approved_at)
    values (p_request_id, auth.uid(), now());

    -- count distinct approvers
    select count(distinct approver_id) into v_cnt
    from public.access_approvals
    where request_id = p_request_id;

    if v_cnt >= 2 then
        update public.access_requests
        set status = 'granted'
        where id = p_request_id;
    end if;

    return (select status from public.access_requests where id = p_request_id);
end;
$$;

-- Grant execute on the RPC to all authenticated users
grant execute on function public.approve_access(bigint) to authenticated;
