-- Function to approve access requests
create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
as $$
declare
    v_uid            uuid := auth.uid();
    v_req_status     text;
    v_req_owner      uuid;
    v_approvals_cnt  int;
begin
    -- must be authenticated
    if v_uid is null then
        raise exception 'Unauthenticated user';
    end if;

    -- caller must be on ops team
    if not exists (select 1 from public.ops_team ot where ot.user_id = v_uid) then
        raise exception 'Caller is not a member of the ops team';
    end if;

    -- fetch request and lock it
    select status, requester_id
      into v_req_status, v_req_owner
      from public.access_requests
      where id = p_request_id
      for update;
    if not found then
        raise exception 'Request % does not exist', p_request_id;
    end if;

    -- request must be pending
    if v_req_status <> 'pending' then
        raise exception 'Request % is not pending', p_request_id;
    end if;

    -- ops member cannot approve their own request
    if v_req_owner = v_uid then
        raise exception 'Requester cannot approve own request';
    end if;

    -- cannot approve twice
    if exists (
        select 1
        from public.access_approvals aa
        where aa.request_id = p_request_id
          and aa.approver_id = v_uid
    ) then
        raise exception 'User has already approved request %', p_request_id;
    end if;

    -- record approval
    insert into public.access_approvals (request_id, approver_id)
    values (p_request_id, v_uid);

    -- count distinct approvers
    select count(distinct approver_id)
      into v_approvals_cnt
      from public.access_approvals
      where request_id = p_request_id;

    -- if two or more distinct ops members approved, grant the request
    if v_approvals_cnt >= 2 then
        update public.access_requests
           set status = 'granted'
         where id = p_request_id;
        v_req_status := 'granted';
    end if;

    return v_req_status;
end;
$$;

