-- Enable row level security
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.issues enable row level security;

-- Helper functions
create or replace function public.is_project_member(p_id bigint)
returns boolean language sql stable as $$
  select exists (
    select 1
    from public.project_members pm
    where pm.project_id = p_id
      and pm.user_id = auth.uid()
  );
$$;

create or replace function public.is_maintainer(p_id bigint)
returns boolean language sql stable as $$
  select exists (
    select 1
    from public.project_members pm
    where pm.project_id = p_id
      and pm.user_id = auth.uid()
      and pm.role = 'maintainer'
  );
$$;

create or replace function public.can_see_issue(i public.issues)
returns boolean language sql stable as $$
  select
    -- member of the project?
    exists (
      select 1
      from public.project_members pm
      where pm.project_id = i.project_id
        and pm.user_id = auth.uid()
    )
    and (
      -- non‑confidential visible to all members
      i.is_confidential = false
      -- confidential visible to maintainers, reporter, or assignee
      or (
        i.is_confidential = true
        and (
          exists (
            select 1
            from public.project_members pm
            where pm.project_id = i.project_id
              and pm.user_id = auth.uid()
              and pm.role = 'maintainer'
          )
          or i.reporter_id = auth.uid()
          or i.assignee_id = auth.uid()
        )
      )
    );
$$;

-- Policies for projects
create policy "project select - members only"
  on public.projects
  for select
  using (
    auth.role() = 'authenticated'
    and public.is_project_member(id)
  );

-- Policies for project_members
create policy "project_members select - members of same project"
  on public.project_members
  for select
  using (
    auth.role() = 'authenticated'
    and public.is_project_member(project_id)
  );

-- Policies for issues
create policy "issues select - visibility rules"
  on public.issues
  for select
  using (
    auth.role() = 'authenticated'
    and public.can_see_issue(issues)
  );

create policy "issues insert - members can file (confidential only by maintainer)"
  on public.issues
  for insert
  with check (
    auth.role() = 'authenticated'
    and public.is_project_member(project_id)
    and (
      is_confidential = false
      or public.is_maintainer(project_id)
    )
  );

create policy "issues update - developers & maintainers can update visible issues"
  on public.issues
  for update
  using (
    auth.role() = 'authenticated'
    and public.can_see_issue(issues)
    and exists (
      select 1
      from public.project_members pm
      where pm.project_id = project_id
        and pm.user_id = auth.uid()
        and pm.role in ('developer','maintainer')
    )
  )
  with check (
    -- keep the same visibility condition after update
    public.can_see_issue(issues)
  );

-- No delete policy (deletions are denied)

-- Triggers to enforce business rules
create or replace function public.issues_before_insert()
returns trigger language plpgsql as $$
begin
  -- enforce reporter as the authenticated user
  NEW.reporter_id := auth.uid();
  -- enforce status always 'open' on creation
  NEW.status := 'open';
  return NEW;
end;
$$;

create trigger issues_before_insert
  before insert on public.issues
  for each row execute function public.issues_before_insert();

create or replace function public.issues_before_update()
returns trigger language plpgsql as $$
declare
  is_maint boolean;
begin
  if NEW.is_confidential is distinct from OLD.is_confidential then
    select exists (
      select 1
      from public.project_members pm
      where pm.project_id = OLD.project_id
        and pm.user_id = auth.uid()
        and pm.role = 'maintainer'
    ) into is_maint;
    if not is_maint then
      raise exception 'Only maintainers can change confidentiality';
    end if;
  end if;
  return NEW;
end;
$$;

create trigger issues_before_update
  before update on public.issues
  for each row execute function public.issues_before_update();

-- Revoke any default privileges that could bypass RLS for anon/authenticated
revoke all on public.projects from public;
revoke all on public.project_members from public;
revoke all on public.issues from public;

-- Ensure service_role can bypass RLS (default behavior, no extra grant needed)
