create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
as $$
declare
    v_patient uuid;
    v_refills int;
    v_expires timestamptz;
    v_new_refills int;
begin
    -- Ensure caller is a pharmacist
    if not exists (select 1 from public.pharmacists where user_id = auth.uid()) then
        raise exception 'Only pharmacists can dispense prescriptions';
    end if;

    -- Lock the prescription row
    select patient_id, refills_left, expires_at
      into v_patient, v_refills, v_expires
    from public.prescriptions
    where id = p_prescription_id
    for update;

    if not found then
        raise exception 'Prescription % not found', p_prescription_id;
    end if;

    if v_patient = auth.uid() then
        raise exception 'Pharmacist cannot dispense own prescription';
    end if;

    if v_expires < now() then
        raise exception 'Prescription % has expired', p_prescription_id;
    end if;

    if v_refills <= 0 then
        raise exception 'Prescription % has no refills left', p_prescription_id;
    end if;

    -- Decrement refills
    update public.prescriptions
       set refills_left = refills_left - 1
     where id = p_prescription_id;

    -- Record the dispense
    insert into public.dispenses (prescription_id, pharmacist_id)
    values (p_prescription_id, auth.uid());

    -- Return remaining refills
    select refills_left into v_new_refills
    from public.prescriptions
    where id = p_prescription_id;

    return v_new_refills;
end;
$$;

-- Grant execute on the RPC to signed‑in users
grant execute on function public.dispense(bigint) to authenticated;
