--------------------------------------------------------------------
-- Helper functions for checkout / checkin
--------------------------------------------------------------------
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
as $$
declare
    v_user uuid := auth.uid();
    v_can_edit boolean;
    v_checked_out_by uuid;
begin
    -- Verify edit access
    select da.can_edit
      into v_can_edit
      from public.doc_access da
     where da.doc_id = p_doc_id
       and da.user_id = v_user
     limit 1;

    if not found or not v_can_edit then
        raise exception 'No edit access to document %', p_doc_id using errcode = 'P0001';
    end if;

    -- Lock the document row
    select d.checked_out_by
      into v_checked_out_by
      from public.documents d
     where d.id = p_doc_id
     for update;

    if not found then
        raise exception 'Document % does not exist', p_doc_id using errcode = 'P0002';
    end if;

    if v_checked_out_by is null or v_checked_out_by = v_user then
        update public.documents
           set checked_out_by = v_user
         where id = p_doc_id;
    else
        raise exception 'Document % is already checked out by another user', p_doc_id using errcode = 'P0003';
    end if;
end;
$$;

create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security definer
as $$
declare
    v_user uuid := auth.uid();
    v_checked_out_by uuid;
begin
    -- Lock the document row
    select d.checked_out_by
      into v_checked_out_by
      from public.documents d
     where d.id = p_doc_id
     for update;

    if not found then
        raise exception 'Document % does not exist', p_doc_id using errcode = 'P0002';
    end if;

    if v_checked_out_by <> v_user then
        raise exception 'Document % is not checked out by the caller', p_doc_id using errcode = 'P0004';
    end if;

    update public.documents
       set body = p_body,
           checked_out_by = null
     where id = p_doc_id;
end;
$$;

-- Grant execute rights on the RPC functions to authenticated users
grant execute on function public.checkout_document(bigint) to authenticated;
grant execute on function public.checkin_document(bigint, text) to authenticated;
