-- -----------------------------------------------------------------
-- checkout_document(p_doc_id bigint)
-- -----------------------------------------------------------------
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
as $$
declare
    v_user uuid := auth.uid();
    v_can_edit boolean;
    v_locked_by uuid;
begin
    -- elevate to service_role to bypass RLS for the internal work
    perform public._set_service_role();

    -- verify the document exists and lock the row
    select checked_out_by
    into v_locked_by
    from public.documents
    where id = p_doc_id
    for update;

    if not found then
        raise exception 'Document % does not exist', p_doc_id using errcode = 'P0001';
    end if;

    -- verify edit access
    select can_edit
    into v_can_edit
    from public.doc_access
    where doc_id = p_doc_id
      and user_id = v_user;

    if not found or not v_can_edit then
        raise exception 'No edit permission for document %', p_doc_id using errcode = 'P0002';
    end if;

    -- verify lock status
    if v_locked_by is not null and v_locked_by <> v_user then
        raise exception 'Document % is already checked out by another user', p_doc_id using errcode = 'P0003';
    end if;

    -- acquire lock (or keep existing lock if already held)
    update public.documents
    set checked_out_by = v_user
    where id = p_doc_id;
end;
$$;

