    into v_locked_by
    from public.documents
    where id = p_doc_id
    for update;

    if not found then
        raise exception 'Document % does not exist', p_doc_id using errcode = 'P0004';
    end if;

    -- ensure the caller holds the lock
    if v_locked_by <> v_user then
        raise exception 'You do not hold the lock on document %', p_doc_id using errcode = 'P0005';
    end if;

    -- save body and release lock
    update public.documents
    set body = p_body,
        checked_out_by = null
    where id = p_doc_id;
end;
$$;

