-- Enable Row Level Security
alter table public.pastes enable row level security;

-- SELECT policy: public non‑private, non‑expired OR owners
create policy select_public on public.pastes
  for select
  using (
    (is_private = false and (expires_at IS NULL or expires_at > now()))
    or (auth.role() = 'authenticated' and author_id = auth.uid())
  );

-- INSERT policy: owners set their own author_id, anon must have none
create policy insert_paste on public.pastes
  for insert
  with check (
    (auth.role() = 'authenticated' and author_id = auth.uid())
    or (auth.role() = 'anon' and author_id IS NULL)
  );

-- DELETE policy: owners can delete, service_role can delete anonymous rows
create policy delete_own on public.pastes
  for delete
  using (
    (author_id = auth.uid())
    or (author_id IS NULL and auth.role() = 'service_role')
  );

-- UPDATE policy: explicitly deny all updates
create policy no_update on public.pastes
  for update
  using (false);

-- Helper function to enforce additional insert constraints
create or replace function public.validate_paste_insert()
returns trigger
language plpgsql
security definer
as $$
begin
  if auth.role() = 'authenticated' then
    if NEW.author_id is distinct from auth.uid() then
      raise exception 'author_id must match the authenticated user';
    end if;
  else  -- anon
    if NEW.author_id is not null then
      raise exception 'Anonymous pastes must not have an author_id';
    end if;
    if NEW.is_private then
      raise exception 'Anonymous pastes cannot be private';
    end if;
  end if;
  return NEW;
end;
$$;

-- Trigger to run the validation before insert
create trigger validate_paste_insert_trigger
  before insert on public.pastes
  for each row execute function public.validate_paste_insert();

-- Grant appropriate privileges to the public roles
grant select, insert, delete on public.pastes to anon, authenticated;
revoke update on public.pastes from anon, authenticated;
