-- Enable Row Level Security on the usage table
alter table public.api_usage enable row level security;

-- Revoke any public privileges and grant only to appropriate roles
revoke all on public.api_usage from public;
revoke all on public.usage_summary from public;

grant select on public.api_usage to authenticated;
grant select on public.api_usage to service_role;
grant select on public.usage_summary to authenticated;
grant select on public.usage_summary to service_role;

-- Policies for api_usage
create policy "authenticated users can read own usage"
    on public.api_usage
    for select
    using (auth.uid() = user_id);

create policy "prevent inserts"
    on public.api_usage
    for insert
    with check (false);

create policy "prevent updates"
    on public.api_usage
    for update
    using (false)
    with check (false);

create policy "prevent deletes"
    on public.api_usage
    for delete
    using (false);

-- Helper function that returns the per‑user usage summary,
-- allowing the service_role to see all rows while normal users see only theirs.
create or replace function public.usage_summary()
returns table (
    user_id uuid,
    total_requests bigint,
    active_days integer
) language sql stable
as $$
    select
        user_id,
        sum(requests) as total_requests,
        count(*) as active_days
    from public.api_usage
    where (auth.role() = 'service_role') or (user_id = auth.uid())
    group by user_id;
$$;

-- View exposing the aggregated usage
create view public.usage_summary as
    select * from public.usage_summary();

-- Ensure the view respects RLS (it will inherit the policies of the underlying table)
alter view public.usage_summary enable row level security;
