-- Enable RLS
alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

-- Helper functions
create or replace function public.is_resident_of_unit(p_user uuid, p_unit bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.residents r
    where r.user_id = p_user
      and r.unit_id = p_unit
  );
$$;

create or replace function public.is_staff_of_building(p_user uuid, p_building bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.building_staff bs
    where bs.user_id = p_user
      and bs.building_id = p_building
  );
$$;

-- Policies for units
create policy "units_select_resident_or_staff"
  on public.units
  for select
  using (
    auth.role() = 'authenticated' and (
      exists (select 1 from public.residents r where r.user_id = auth.uid() and r.unit_id = units.id)
      or exists (select 1 from public.building_staff bs where bs.user_id = auth.uid() and bs.building_id = units.building_id)
    )
  );

-- Policies for residents
create policy "residents_select_self"
  on public.residents
  for select
  using (auth.uid() = user_id);

-- Policies for building_staff
create policy "building_staff_select_self"
  on public.building_staff
  for select
  using (auth.uid() = user_id);

-- Policies for requests
create policy "requests_select_allowed"
  on public.requests
  for select
  using (
    auth.role() = 'authenticated' and (
      exists (select 1 from public.residents r where r.user_id = auth.uid() and r.unit_id = requests.unit_id)
      or exists (
        select 1
        from public.units u
        join public.building_staff bs on bs.building_id = u.building_id
        where bs.user_id = auth.uid()
          and u.id = requests.unit_id
      )
    )
  );

create policy "requests_insert_resident"
  on public.requests
  for insert
  with check (
    auth.role() = 'authenticated'
    and created_by = auth.uid()
    and public.is_resident_of_unit(auth.uid(), requests.unit_id)
    and (status = 'open' or status is null)
  );

create policy "requests_update_status_staff"
  on public.requests
  for update
  using (
    auth.role() = 'authenticated'
    and exists (
      select 1
      from public.units u
      join public.building_staff bs on bs.building_id = u.building_id
      where bs.user_id = auth.uid()
        and u.id = requests.unit_id
    )
  )
  with check (
    new.unit_id = old.unit_id
    and new.created_by = old.created_by
    and new.description = old.description
    and new.status in ('open','in_progress','done')
  );

-- Policies for request_photos
create policy "request_photos_select_allowed"
  on public.request_photos
  for select
  using (
    auth.role() = 'authenticated' and (
      exists (
        select 1
        from public.requests req
        join public.residents r on r.unit_id = req.unit_id
        where r.user_id = auth.uid()
          and req.id = request_photos.request_id
      )
      or exists (
        select 1
        from public.requests req
        join public.units u on u.id = req.unit_id
        join public.building_staff bs on bs.building_id = u.building_id
        where bs.user_id = auth.uid()
          and req.id = request_photos.request_id
      )
    )
  );

create policy "request_photos_insert_allowed"
  on public.request_photos
  for insert
  with check (
    auth.role() = 'authenticated' and (
      exists (
        select 1
