-- Enable Row Level Security
alter table public.items enable row level security;
alter table public.claims enable row level security;

-- Ensure at most one approved claim per item
create unique index claims_item_approved_idx on public.claims (item_id) where status = 'approved';

-- ==============================
-- Items policies
-- ==============================
-- R1: Signed‑in users can see every item
create policy items_select on public.items
  for select
  using (auth.role() = 'authenticated');

-- R1: Finders can post items as themselves (found_by = auth.uid())
create policy items_insert on public.items
  for insert
  with check (found_by = auth.uid());

-- R1: Finders can update only their own items
create policy items_update on public.items
  for update
  using (found_by = auth.uid())
  with check (found_by = auth.uid());

-- ==============================
-- Claims policies
-- ==============================
-- R2: Claimants see own claims; finders see claims on their items
create policy claims_select on public.claims
  for select
  using (
    claimant_id = auth.uid()
    or item_id in (select id from public.items where found_by = auth.uid())
  );

-- R3: Users can claim open items they did not find; new claims are always pending
create policy claims_insert on public.claims
  for insert
  with check (
    claimant_id = auth.uid()
    and status = 'pending'
    and exists (
      select 1
      from public.items i
      where i.id = item_id
        and i.status = 'open'
        and i.found_by <> auth.uid()
    )
  );

-- R4: Only the finder can approve/reject a pending claim on their item;
--     claimants cannot modify claims; other columns are immutable
create policy claims_update on public.claims
  for update
  using (
    (select found_by from public.items i where i.id = claims.item_id) = auth.uid()
    and status = 'pending'          -- old status must be pending
  )
  with check (
    item_id = old.item_id
    and claimant_id = old.claimant_id
    and message = old.message
    and status in ('approved','rejected')
  );

-- ==============================
-- Permissions for authenticated users
-- ==============================
grant select, insert, update on public.items to authenticated;
grant select, insert, update on public.claims to authenticated;

-- Anonymous users have no access
revoke all on public.items from anon;
revoke all on public.claims from anon;
