-- Enable RLS
alter table public.fleet_managers enable row level security;
alter table public.vehicles enable row level security;
alter table public.assignments enable row level security;
alter table public.trips enable row level security;

-- Helper function to verify a trip is covered by an assignment
create or replace function public.is_trip_covered(p_vehicle_id bigint, p_driver_id uuid, p_trip_date date)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.assignments a
    where a.vehicle_id = p_vehicle_id
      and a.driver_id = p_driver_id
      and p_trip_date between a.starts_on and a.ends_on
  );
$$;

-- fleet_managers: no modifications through the app
create policy "fleet_managers_no_change" on public.fleet_managers
  for all
  using (false)               -- never matches, blocks SELECT/UPDATE/DELETE
  with check (false);         -- blocks INSERT/UPDATE

-- vehicles: any signed‑in user can read
create policy "vehicles_select_authenticated" on public.vehicles
  for select
  using (auth.role() = 'authenticated');

-- assignments: drivers see own, managers see all; only managers can modify
create policy "assignments_select_owner_or_manager" on public.assignments
  for select
  using (
    auth.uid() = driver_id
    or exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  );

create policy "assignments_manage_by_manager" on public.assignments
  for all
  using (
    exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  )
  with check (
    exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  );

-- trips: drivers see own, managers see all
create policy "trips_select_owner_or_manager" on public.trips
  for select
  using (
    auth.uid() = driver_id
    or exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  );

-- drivers insert trips only when covered by an assignment
create policy "trips_insert_driver_covered" on public.trips
  for insert
  with check (
    auth.uid() = driver_id
    and public.is_trip_covered(vehicle_id, driver_id, trip_date)
  );

-- drivers update their own trips; still must be covered; managers can also update any trip
create policy "trips_update_driver_or_manager" on public.trips
  for update
  using (
    auth.uid() = driver_id
    or exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  )
  with check (
    auth.uid() = driver_id
    and public.is_trip_covered(vehicle_id, driver_id, trip_date)
  );

-- drivers delete their own trips; managers can delete any
create policy "trips_delete_owner_or_manager" on public.trips
  for delete
  using (
    auth.uid() = driver_id
    or exists (select 1 from public.fleet_managers fm where fm.user_id = auth.uid())
  );
