-- Enable Row Level Security
alter table public.listings enable row level security;
alter table public.orders   enable row level security;

-- Policies --------------------------------------------------------------

-- Listings: any signed‑in user can read all listings
create policy listings_select on public.listings
  for select
  to authenticated
  using (true);

-- Orders: a user can read orders where they are buyer or seller
create policy orders_select on public.orders
  for select
  to authenticated
  using (buyer_id = auth.uid() or seller_id = auth.uid());

-- Orders: a buyer can insert a new order only if it matches the listing
create policy orders_insert on public.orders
  for insert
  to authenticated
  with check (
    buyer_id = auth.uid()                                            -- buyer is caller
    and buyer_id <> (select seller_id from public.listings where id = listing_id)   -- cannot buy own listing
    and seller_id = (select seller_id from public.listings where id = listing_id)   -- seller matches listing
    and amount    = (select price      from public.listings where id = listing_id)   -- amount matches price
    and coalesce(status, 'pending_payment') = 'pending_payment'                     -- status is pending_payment
  );

-- No UPDATE or DELETE policies for orders → they cannot be changed directly
-- (service_role bypasses RLS and retains full access)

-- Functions --------------------------------------------------------------

-- Mark order as shipped (seller only, from paid → shipped)
create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  _order public.orders%rowtype;
begin
  if auth.role() <> 'authenticated' then
    raise exception 'Only authenticated users may call this function';
  end if;

  select * into _order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order % does not exist', p_order_id;
  end if;

  if _order.status <> 'paid' then
    raise exception 'Order % must be in status paid to be shipped', p_order_id;
  end if;

  if _order.seller_id <> auth.uid() then
    raise exception 'Only the seller can ship order %', p_order_id;
  end if;

  update public.orders
  set status = 'shipped'
  where id = p_order_id;

  return 'shipped';
end;
$$;

-- Release funds (buyer only, from shipped → released)
create or replace function public.release_funds(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  _order public.orders%rowtype;
begin
  if auth.role() <> 'authenticated' then
    raise exception 'Only authenticated users may call this function';
  end if;

  select * into _order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order % does not exist', p_order_id;
  end if;

  if _order.status <> 'shipped' then
    raise exception 'Order % must be in status shipped to release funds', p_order_id;
  end if;

  if _order.buyer_id <> auth.uid() then
    raise exception 'Only the buyer can release funds for order %', p_order_id;
  end if;

  update public.orders
  set status = 'released'
  where id = p_order_id;

  return 'released';
end;
$$;

-- Refund order (seller only, from paid/shipped → refunded)
create or replace function public.refund_order(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  _order public.orders%rowtype;
begin
  if auth.role() <> 'authenticated' then
    raise exception 'Only authenticated users may call this function';
  end if;

  select * into _order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'Order % does not exist', p_order_id;
  end if;

  if _order.status not in ('paid','shipped') then
    raise exception 'Order % must be paid or shipped to be refunded', p_order_id;
  end if;

  if _order.seller_id <> auth.uid() then
    raise exception 'Only the seller can refund order %', p_order_id;
  end if;

  update public.orders
  set status = 'refunded'
  where id = p_order_id;

  return 'refunded';
end;
$$;

-- Grants -----------------------------------------------------------------

grant select on public.listings to authenticated;
grant select on public.orders   to authenticated;

grant execute on function public.mark_shipped(bigint)   to authenticated;
grant execute on function public.release_funds(bigint)  to authenticated;
grant execute on function public.refund_order(bigint)  to authenticated;

