create or replace function public.validate_order_insert()
returns trigger
language plpgsql
security definer
as $$
declare
    l public.listings;
begin
    -- Ensure buyer is the authenticated user
    if new.buyer_id <> auth.uid() then
        raise exception 'buyer_id must match authenticated user';
    end if;

    -- Fetch the related listing
    select * into l from public.listings where id = new.listing_id;
    if not found then
        raise exception 'listing % does not exist', new.listing_id;
    end if;

    -- Prevent buying own listing
    if l.seller_id = auth.uid() then
        raise exception 'cannot purchase your own listing';
    end if;

    -- Ensure seller_id and amount match the listing
    if new.seller_id <> l.seller_id then
        raise exception 'seller_id must match listing seller';
    end if;
    if new.amount <> l.price then
        raise exception 'amount must equal listing price';
    end if;

    -- Force status to pending_payment
    new.status := 'pending_payment';

    return new;
end;
$$;

