-- Enable RLS on the tables
alter table public.customers enable row level security;
alter table public.support_agents enable row level security;
alter table public.supervisors enable row level security;

-- Revoke default privileges and grant only to appropriate roles
revoke all on public.customers from public;
revoke all on public.support_agents from public;
revoke all on public.supervisors from public;

grant select on public.customers to authenticated, service_role;
grant select on public.support_agents to authenticated, service_role;
grant select on public.supervisors to authenticated, service_role;

-- Policies for customers (R1)
create policy "supervisors can read customers"
    on public.customers
    for select
    using (exists (
        select 1
        from public.supervisors s
        where s.user_id = auth.uid()
    ));

-- Policies for support_agents (R4)
create policy "agents can see own row"
    on public.support_agents
    for select
    using (user_id = auth.uid());

-- Policies for supervisors (R4)
create policy "supervisors can see own row"
    on public.supervisors
    for select
    using (user_id = auth.uid());

-- Helper functions for masking (R2)
create or replace function public.mask_email(email text)
returns text
language sql
immutable
as $$
    select
        case
            when email is null then null
            else left(email, 1) || '***' || substring(email from '@.*')
        end;
$$;

create or replace function public.mask_phone(phone text)
returns text
language sql
immutable
as $$
    select
        case
            when phone is null then null
            else repeat('*', 6) || right(phone, 4)
        end;
$$;

-- View for support agents (R2, R3, R6)
create or replace view public.support_customers
with (security_barrier) as
select
    c.id,
    c.region,
    c.full_name,
    public.mask_email(c.email)   as email_masked,
    public.mask_phone(c.phone)   as phone_masked
from public.customers c
join public.support_agents a
    on a.region = c.region;

-- Grant access to the view (agents and supervisors via RLS, service_role bypasses RLS)
grant select on public.support_customers to authenticated, service_role;
