-- Policies
create policy journal_entries_select_own
  on public.journal_entries
  for select
  using (auth.uid() = user_id);

create policy journal_entries_insert_own
  on public.journal_entries
  for insert
  with check (auth.uid() = user_id);

create policy journal_entries_update_own
  on public.journal_entries
  for update
  using (auth.uid() = user_id
         and now() <= created_at + interval '24 hours')
  with check (auth.uid() = user_id);

create policy journal_entries_delete_own
  on public.journal_entries
  for delete
  using (auth.uid() = user_id
         and now() <= created_at + interval '24 hour');

-- Helper function to enforce immutable fields and default timestamps
create or replace function public.journal_entries_timestamp()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    -- ensure user_id always matches the authenticated user (even if omitted)
    if new.user_id is null then
      new.user_id := auth.uid();
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if new.created_at <> old.created_at then
      raise exception 'created_at cannot be modified';
    end if;
    if new.user_id <> old.user_id then
      raise exception 'user_id cannot be modified';
    end if;
    return new;
  end if;
  return null;
end;
$$;

-- Trigger to apply the helper function
create trigger journal_entries_timestamp_trg
  before insert or update on public.journal_entries
  for each row execute function public.journal_entries_timestamp();

-- Grants
grant select, insert, update, delete on public.journal_entries to authenticated;
revoke all on public.journal_entries from anon;
