returns trigger
language plpgsql
security definer
as $$
begin
    if tg_op = 'INSERT' then
        -- Force correct ownership and timestamp
        new.user_id    := auth.uid();
        new.created_at := now();
        return new;
    elsif tg_op = 'UPDATE' then
        -- Prevent changes to ownership or timestamp
        if new.user_id is distinct from old.user_id then
