-- Enable Row Level Security
alter table public.projects enable row level security;
alter table public.translators enable row level security;
alter table public.segments enable row level security;

-- Helper function to protect immutable columns and prevent changes to reviewed rows
create or replace function public.enforce_segment_immutable()
returns trigger language plpgsql as $$
begin
  -- immutable columns
  if new.project_id <> old.project_id then
    raise exception 'project_id is immutable';
  end if;
  if new.lang <> old.lang then
    raise exception 'lang is immutable';
  end if;
  if new.source_text <> old.source_text then
    raise exception 'source_text is immutable';
  end if;
  -- reviewed rows are read‑only
  if old.status = 'reviewed' then
    raise exception 'reviewed segments cannot be modified';
  end if;
  return new;
end;
$$;

create trigger trg_enforce_segment_immutable
before update on public.segments
for each row execute function public.enforce_segment_immutable();

-- Policies for projects
create policy "projects_select_assigned"
  on public.projects
  for select
  using (
    exists (
      select 1
      from public.translators t
      where t.project_id = projects.id
        and t.user_id = auth.uid()
    )
  );

-- Policies for translators (assignment rows)
create policy "translators_select_own"
  on public.translators
  for select
  using (user_id = auth.uid());

-- Policies for segments (read)
create policy "segments_select_assigned_lang"
  on public.segments
  for select
  using (
    exists (
      select 1
      from public.translators t
      where t.project_id = segments.project_id
        and t.lang = segments.lang
        and t.user_id = auth.uid()
    )
  );

-- Policy: Translators can update draft translations in their language
create policy "segments_update_by_translator"
  on public.segments
  for update
  using (
    old.status = 'draft' and
    exists (
      select 1
      from public.translators t
      where t.project_id = segments.project_id
        and t.lang = segments.lang
        and t.user_id = auth.uid()
        and t.role = 'translator'
    )
  )
  with check (
    new.translated_by = auth.uid() and
    new.target_text is not null and
    new.status = old.status and               -- cannot change status
    new.source_text = old.source_text and
    new.project_id = old.project_id and
    new.lang = old.lang
  );

-- Policy: Reviewers can mark draft segments as reviewed (and optionally edit translation)
create policy "segments_update_by_reviewer"
  on public.segments
  for update
  using (
    old.status = 'draft' and
    exists (
      select 1
      from public.translators t
      where t.project_id = segments.project_id
        and t.lang = segments.lang
        and t.user_id = auth.uid()
        and t.role = 'reviewer'
    )
  )
  with check (
    new.status = 'reviewed' and
    new.source_text = old.source_text and
    new.project_id = old.project_id and
    new.lang = old.lang
  );

-- Ensure anonymous role cannot read anything (no policies for anon, default deny)
revoke all on public.projects from anon;
revoke all on public.translators from anon;
revoke all on public.segments from anon;

-- Grant read access to authenticated role (policies will filter rows)
grant select on public.projects to authenticated;
grant select on public.translators to authenticated;
grant select, update on public.segments to authenticated;
