  for select
  using (
    exists (
      select 1
      from public.translators t
      where t.project_id = projects.id
        and t.user_id = auth.uid()
    )
  );

-- Translators: users can see only their own assignment rows
create policy translator_select on public.translators
  for select
  using (user_id = auth.uid());

-- Segments: users can see segments of languages they are assigned to (any role)
create policy segment_select on public.segments
  for select
  using (
    exists (
      select 1
      from public.translators t
      where t.project_id = segments.project_id
        and t.user_id = auth.uid()
        and t.lang = segments.lang
    )
  );

-- Translators: can edit draft segments in their language, recording themselves
create policy segment_update_translator on public.segments
  for update
  using (
    status = 'draft'
    and public.is_assigned(project_id, lang, 'translator')
  )
  with check (
    -- status may not be changed
    new.status = old.status
    -- source text is immutable
    and new.source_text = old.source_text
    -- translation author must be the caller
    and new.translated_by = auth.uid()
    -- optional: prevent changing immutable columns
    and new.id = old.id
    and new.project_id = old.project_id
    and new.lang = old.lang
  );

-- Reviewers: can mark draft segments as reviewed (and optionally edit translation)
create policy segment_update_reviewer on public.segments
  for update
  using (
    status = 'draft'
    and public.is_assigned(project_id, lang, 'reviewer')
  )
  with check (
    -- status can only move to 'reviewed' (or stay unchanged)
    (new.status = 'reviewed' or new.status = old.status)
    -- source text is immutable
    and new.source_text = old.source_text
    -- reviewer cannot change the author of the translation
    and new.translated_by = old.translated_by
    -- optional: prevent changing immutable columns
    and new.id = old.id
