-- Enable Row Level Security
alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.lab_results enable row level security;

-- Helper functions
create or replace function public.is_doctor_of_patient(p_doctor uuid, p_patient bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.care_team ct
    where ct.patient_id = p_patient
      and ct.doctor_id = p_doctor
  );
$$;

create or replace function public.can_edit_lab_result(p_doctor uuid, p_patient bigint, p_old_released timestamptz)
returns boolean
language sql
stable
as $$
  select public.is_doctor_of_patient(p_doctor, p_patient)
    and (p_old_released is null or p_old_released > now());
$$;

-- Policies for patients
create policy "patients select self or care‑team" on public.patients
for select
using (
  auth.role() = 'service_role'
  or user_id = auth.uid()
  or public.is_doctor_of_patient(auth.uid(), id)
);

-- No insert / update / delete for non‑service_role (no policies needed – default deny)

-- Policies for care_team
create policy "care_team select for patient or doctor" on public.care_team
for select
using (
  auth.role() = 'service_role'
  or doctor_id = auth.uid()
  or exists (
        select 1
        from public.patients p
        where p.id = care_team.patient_id
          and p.user_id = auth.uid()
      )
);

-- Policies for lab_results
create policy "lab_results select – patient (released) or doctor" on public.lab_results
for select
using (
  auth.role() = 'service_role'
  or (
        exists (
          select 1
          from public.patients p
          where p.id = lab_results.patient_id
            and p.user_id = auth.uid()
        )
        and lab_results.released_at is not null
        and lab_results.released_at <= now()
     )
  or public.is_doctor_of_patient(auth.uid(), lab_results.patient_id)
);

create policy "lab_results insert – only doctor in care team" on public.lab_results
for insert
with check (
  auth.role() = 'service_role'
  or public.is_doctor_of_patient(auth.uid(), NEW.patient_id)
);

create policy "lab_results update – doctor before release" on public.lab_results
for update
using (
  auth.role() = 'service_role'
  or public.can_edit_lab_result(auth.uid(), lab_results.patient_id, lab_results.released_at)
)
with check (
  auth.role() = 'service_role'
  or (NEW.released_at is null or NEW.released_at >= now())
);

-- No delete policies (default deny)

-- Privilege management
revoke all on public.patients from public;
revoke all on public.care_team from public;
revoke all on public.lab_results from public;

grant select on public.patients to authenticated;
grant select on public.care_team to authenticated;
grant select, insert, update on public.lab_results to authenticated;

