-- Enable Row Level Security
alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.lab_results enable row level security;

-- Helper function to check doctor membership in a patient's care team
create or replace function public.is_doctor_in_care(p_patient_id bigint, p_doctor_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.care_team ct
    where ct.patient_id = p_patient_id
      and ct.doctor_id = p_doctor_id
  );
$$;

-- Helper function to check patient ownership
create or replace function public.is_patient_owner(p_patient_id bigint, p_user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.patients p
    where p.id = p_patient_id
      and p.user_id = p_user_id
  );
$$;

-------------------------------------------------
-- patients table policies
-------------------------------------------------
create policy "patients_select_self_or_care_doctor"
  on public.patients
  for select
  using (
    auth.role() = 'authenticated' and (
      user_id = auth.uid()
      or public.is_doctor_in_care(id, auth.uid())
    )
  );

-- No insert / update / delete policies (R4)

-------------------------------------------------
-- care_team table policies
-------------------------------------------------
create policy "care_team_select_self_or_doctor"
  on public.care_team
  for select
  using (
    auth.role() = 'authenticated' and (
      doctor_id = auth.uid()
      or public.is_patient_owner(patient_id, auth.uid())
    )
  );

-- No insert / update / delete policies (R4)

-------------------------------------------------
-- lab_results table policies
-------------------------------------------------
create policy "lab_results_select"
  on public.lab_results
  for select
  using (
    auth.role() = 'authenticated' and (
      -- patient can see released results
      (public.is_patient_owner(patient_id, auth.uid())
       and released_at is not null
       and released_at <= now())
      -- doctors in care team can see everything
      or public.is_doctor_in_care(patient_id, auth.uid())
    )
  );

create policy "lab_results_insert"
  on public.lab_results
  for insert
  with check (
    auth.role() = 'authenticated'
    and public.is_doctor_in_care(NEW.patient_id, auth.uid())
  );

create policy "lab_results_update_unreleased"
  on public.lab_results
  for update
  using (
    auth.role() = 'authenticated'
    and public.is_doctor_in_care(patient_id, auth.uid())
    and (released_at is null or released_at > now())
  )
  with check (
    auth.role() = 'authenticated'
    and public.is_doctor_in_care(patient_id, auth.uid())
    and (released_at is null or released_at > now())
  );

-- No delete policy (R4)

-------------------------------------------------
-- Triggers to enforce immutability after release
-------------------------------------------------
create or replace function public.prevent_lab_result_modifications()
returns trigger
language plpgsql
as $$
begin
  -- Allow full access for the service_role (bypasses RLS)
  if current_user = 'service_role' then
    return NEW;
  end if;

  if TG_OP = 'UPDATE' then
    if OLD.released_at is not null and OLD.released_at <= now() then
      raise exception 'Cannot modify a lab result that has already been released.';
    end if;
    return NEW;
  elsif TG_OP = 'DELETE' then
    raise exception 'Lab results cannot be deleted.';
  end if;
  return NEW;
end;
$$;

create trigger trg_prevent_lab_result_modifications
  before update or delete on public.lab_results
  for each row execute function public.prevent_lab_result_modifications();

-------------------------------------------------
-- Revoke any default privileges from anon (defense in depth)
-------------------------------------------------
revoke all on public.patients from anon;
revoke all on public.care_team from anon;
revoke all on public.lab_results from anon;

-- Ensure authenticated role has only SELECT on patients & care_team, and SELECT/INSERT/UPDATE on lab_results as governed by policies
grant select on public.patients to authenticated;
grant select on public.care_team to authenticated;
grant select, insert, update on public.lab_results to authenticated;
