--------------------------------------------------------------------
-- Helper function to check envelope existence and lock the row
create or replace function public._lock_envelope(p_envelope_id bigint)
returns record
language plpgsql
security definer
as $$
declare
    r record;
begin
    select id, sender_id, status
    into r
    from public.envelopes
    where id = p_envelope_id
    for update;

    if not found then
        raise exception 'Envelope % does not exist', p_envelope_id;
    end if;

    return r;
end;
$$;

--------------------------------------------------------------------
-- RPC: sign_envelope
create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
    v_envelope record;
    v_recipient record;
    v_signed_count int;
    v_total_count int;
    v_user_id uuid := auth.uid();
begin
    -- lock envelope row
    v_envelope := public._lock_envelope(p_envelope_id);

    if v_envelope.status <> 'sent' then
        raise exception 'Envelope % is not in sent status', p_envelope_id;
    end if;

    -- fetch recipient row for caller
    select sign_order, signed_at
    into v_recipient
    from public.envelope_recipients
    where envelope_id = p_envelope_id
      and user_id = v_user_id;

    if not found then
        raise exception 'User % is not a recipient of envelope %', v_user_id, p_envelope_id;
    end if;

    if v_recipient.signed_at is not null then
        raise exception 'User % has already signed envelope %', v_user_id, p_envelope_id;
    end if;

    -- ensure all earlier sign_order rows are already signed
    if exists (
        select 1
        from public.envelope_recipients er
        where er.envelope_id = p_envelope_id
          and er.sign_order < v_recipient.sign_order
          and er.signed_at is null
    ) then
        raise exception 'Previous recipient(s) have not signed envelope % yet', p_envelope_id;
    end if;

    -- record the signature
    update public.envelope_recipients
    set signed_at = now()
    where envelope_id = p_envelope_id
      and user_id = v_user_id;

    -- check if all recipients have signed
    select count(*) filter (where signed_at is not null),
           count(*)
    into v_signed_count, v_total_count
    from public.envelope_recipients
    where envelope_id = p_envelope_id;

    if v_signed_count = v_total_count then
        update public.envelopes
        set status = 'completed'
        where id = p_envelope_id;
    end if;

    return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

--------------------------------------------------------------------
-- RPC: void_envelope
create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
as $$
declare
    v_envelope record;
    v_user_id uuid := auth.uid();
begin
    -- lock envelope row
    v_envelope := public._lock_envelope(p_envelope_id);

    if v_envelope.sender_id <> v_user_id then
        raise exception 'Only the sender can void envelope %', p_envelope_id;
    end if;

    if v_envelope.status <> 'sent' then
        raise exception 'Envelope % is not in sent status and cannot be voided', p_envelope_id;
    end if;

    update public.envelopes
    set status = 'voided'
    where id = p_envelope_id;

    return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

