  select count(*) into v_pending_cnt
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and sign_order < v_sign_order
    and signed_at is null;
  if v_pending_cnt > 0 then
    raise exception 'Previous recipients have not signed envelope %', p_envelope_id;
  end if;

