  -- fetch the caller's recipient row and lock it
  select *
    into v_recipient
    from public.envelope_recipients er
   where er.envelope_id = p_envelope_id
     and er.user_id = v_user
   for update;

  if not found then
    raise exception 'User is not a recipient of this envelope';
  end if;

  if v_recipient.signed_at is not null then
    raise exception 'User has already signed this envelope';
  end if;

  -- fetch envelope and lock it
  select status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if v_status <> 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- ensure all prior recipients have signed
  if exists (
    select 1
      from public.envelope_recipients er2
     where er2.envelope_id = p_envelope_id
       and er2.sign_order < v_recipient.sign_order
       and er2.signed_at is null
  ) then
    raise exception 'Previous recipient(s) have not signed yet';
  end if;

  -- record the signature
  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_user;

  -- check if every recipient has signed
  select not exists (
    select 1
      from public.envelope_recipients er3
     where er3.envelope_id = p_envelope_id
       and er3.signed_at is null
  ) into v_all_signed;

  if v_all_signed then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$;

