-- Helper functions to extract tenant and role from JWT
create or replace function public.current_tenant() returns text
stable
language sql as $$
  select nullif(auth.jwt() -> 'app_metadata' ->> 'tenant_id', '');
$$;

create or replace function public.current_user_role() returns text
stable
language sql as $$
  select nullif(auth.jwt() -> 'app_metadata' ->> 'role', '');
$$;

-- Enable Row Level Security
alter table public.items enable row level security;
alter table public.item_shares enable row level security;

-- ==========================
-- Policies for public.items
-- ==========================

-- R1: Read own tenant items or shared (non‑expired) items
create policy "items_select"
  on public.items
  for select
  using (
    tenant_id = public.current_tenant()
    or exists (
      select 1
      from public.item_shares s
      where s.item_id = items.id
        and s.target_tenant = public.current_tenant()
        and (s.expires_at is null or s.expires_at > now())
    )
  );

-- R2: Only admins of the owning tenant can insert items
create policy "items_insert"
  on public.items
  for insert
  with check (
    tenant_id = public.current_tenant()
    and public.current_user_role() = 'admin'
  );

-- R2: Only admins of the owning tenant can update items (cannot change tenant_id)
create policy "items_update"
  on public.items
  for update
  using (
    tenant_id = public.current_tenant()
    and public.current_user_role() = 'admin'
  )
  with check (
    tenant_id = public.current_tenant()  -- prevent moving to another tenant
  );

-- R2: Only admins of the owning tenant can delete items
create policy "items_delete"
  on public.items
  for delete
  using (
    tenant_id = public.current_tenant()
    and public.current_user_role() = 'admin'
  );

-- ==============================
-- Policies for public.item_shares
-- ==============================

-- R4: Read shares of own items OR shares addressed to own tenant
create policy "item_shares_select"
  on public.item_shares
  for select
  using (
    (select i.tenant_id from public.items i where i.id = item_shares.item_id) = public.current_tenant()
    or target_tenant = public.current_tenant()
  );

-- R3: Only admins of the owning tenant can create shares
create policy "item_shares_insert"
  on public.item_shares
  for insert
  with check (
    (select i.tenant_id from public.items i where i.id = NEW.item_id) = public.current_tenant()
    and public.current_user_role() = 'admin'
  );

-- R3: Only admins of the owning tenant can update shares (cannot change item_id to another tenant)
create policy "item_shares_update"
  on public.item_shares
  for update
  using (
    (select i.tenant_id from public.items i where i.id = item_shares.item_id) = public.current_tenant()
    and public.current_user_role() = 'admin'
  )
  with check (
    (select i.tenant_id from public.items i where i.id = NEW.item_id) = public.current_tenant()
  );

-- R3: Only admins of the owning tenant can delete shares
create policy "item_shares_delete"
  on public.item_shares
  for delete
  using (
    (select i.tenant_id from public.items i where i.id = item_shares.item_id) = public.current_tenant()
    and public.current_user_role() = 'admin'
  );

-- ==========================
-- Grants (optional but recommended)
-- ==========================
grant usage on schema public to anon, authenticated;
grant select, insert, update, delete on public.items to anon, authenticated;
grant select, insert, update, delete on public.item_shares to anon, authenticated;
grant execute on function public.current_tenant() to anon, authenticated;
grant execute on function public.current_user_role() to anon, authenticated;
