-- Enable Row Level Security
alter table public.board_notes enable row level security;

-- SELECT: anyone (anon or authenticated) can read all notes
create policy "allow select for everyone"
    on public.board_notes
    for select
    using (true);

-- INSERT: only signed‑in users can insert, author_id must match their UID,
-- is_pinned must never be set by a user
create policy "allow insert for authenticated users"
    on public.board_notes
    for insert
    with check (
        auth.uid() IS NOT NULL
        and author_id = auth.uid()
        and coalesce(is_pinned, false) = false
    );

-- UPDATE: authors can edit their own notes but cannot touch is_pinned
create policy "allow update for owners"
    on public.board_notes
    for update
    using (auth.uid() = author_id)
    with check (new.is_pinned = old.is_pinned);

-- DELETE: authors can delete their own notes
create policy "allow delete for owners"
    on public.board_notes
    for delete
    using (auth.uid() = author_id);

-- Helper function to enforce author_id and protect is_pinned for non‑service_role users
create function public.board_notes_before_write()
returns trigger
language plpgsql
security definer
as $$
begin
    -- Bypass all checks for the privileged service_role
    if current_setting('role') = 'service_role' then
        return new;
    end if;

    -- INSERT: force author_id to the JWT UID and forbid is_pinned
    if TG_OP = 'INSERT' then
        new.author_id := auth.uid();
        new.is_pinned := false;
        return new;
    end if;

    -- UPDATE: prevent changing author_id or is_pinned
    if TG_OP = 'UPDATE' then
        if new.author_id <> old.author_id then
            raise exception 'author_id cannot be changed';
        end if;
        if new.is_pinned <> old.is_pinned then
            raise exception 'is_pinned cannot be changed by non‑moderators';
        end if;
        return new;
    end if;

    return new;
end;
$$;

-- Trigger to invoke the helper before INSERT or UPDATE
create trigger board_notes_protect_before_write
    before insert or update on public.board_notes
    for each row execute function public.board_notes_before_write();

-- Grant SELECT to anonymous and authenticated roles (policy already allows it)
grant select on public.board_notes to anon, authenticated;
```

