-- Enable Row Level Security
alter table public.events enable row level security;
alter table public.checkins enable row level security;

-- Helper function to check if an event is live
create or replace function public.is_event_live(event_id bigint)
returns boolean
language sql
stable
as $$
  select now() between e.starts_at and e.ends_at
  from public.events e
  where e.id = event_id;
$$;

-- Trigger to enforce immutable checked_in_at and correct user_id
create or replace function public.set_checkin_defaults()
returns trigger
language plpgsql
as $$
begin
  new.checked_in_at := now();
  new.user_id := auth.uid();
  return new;
end;
$$;

create trigger set_checkin_defaults
before insert on public.checkins
for each row
execute function public.set_checkin_defaults();

-- Policies

-- R1: Authenticated users can read all events
create policy "events select for authenticated"
  on public.events
  for select
  using (auth.role() = 'authenticated');

-- R1: Authenticated users can read only their own check‑ins
create policy "checkins select own"
  on public.checkins
  for select
  using (auth.uid() = user_id);

-- R2: Authenticated users can insert a check‑in for themselves only while the event is live
create policy "checkins insert own while live"
  on public.checkins
  for insert
  with check (
    auth.uid() = user_id
    and public.is_event_live(new.event_id)
  );

-- No UPDATE or DELETE policies for checkins → those actions are denied for non‑service_role users

-- Grants

grant select on public.events to authenticated;
grant select, insert on public.checkins to authenticated;

revoke all on public.events from anon;
revoke all on public.checkins from anon;
