-- Enable Row Level Security
alter table public.garages enable row level security;
alter table public.mechanics enable row level security;
alter table public.jobs enable row level security;

-- Revoke default privileges (service_role bypasses RLS)
revoke all on public.garages from public;
revoke all on public.mechanics from public;
revoke all on public.jobs from public;

-- Helper function: is the current user a mechanic of a garage?
create or replace function public.is_mechanic(p_garage_id bigint, p_user uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.mechanics m
    where m.garage_id = p_garage_id
      and m.user_id = p_user
  );
$$;

-- Helper function: validate status transitions (used in trigger)
create or replace function public.validate_job_status_transition()
returns trigger
language plpgsql
as $$
begin
  -- -----------------------------------------------------------------
  -- Customer actions
  -- -----------------------------------------------------------------
  if auth.uid() = old.customer_id then
    -- only allowed transition: quoted -> approved, nothing else may change
    if old.status <> 'quoted' then
      raise exception 'Customer can only approve a quoted job';
    end if;
    if new.status <> 'approved' then
      raise exception 'Customer may only set status to approved';
    end if;
    if new.quote_amount <> old.quote_amount then
      raise exception 'Customer cannot modify quote amount';
    end if;
    if new.garage_id <> old.garage_id
       or new.customer_id <> old.customer_id
       or new.vehicle <> old.vehicle then
      raise exception 'Customer cannot modify other fields';
    end if;
    return new;
  end if;

  -- -----------------------------------------------------------------
  -- Mechanic actions (must be a mechanic of the job's garage)
  -- -----------------------------------------------------------------
  if public.is_mechanic(old.garage_id, auth.uid()) then
    -- quoted: mechanics may only edit quote_amount, status must stay quoted
    if old.status = 'quoted' then
      if new.status <> 'quoted' then
        raise exception 'Mechanic cannot change status while job is quoted';
      end if;
      if new.quote_amount = old.quote_amount then
        -- no change, still allowed
        null;
      end if;
      if new.garage_id <> old.garage_id
         or new.customer_id <> old.customer_id
         or new.vehicle <> old.vehicle then
        raise exception 'Mechanic cannot modify fields other than quote_amount while quoted';
      end if;
      return new;
    end if;

    -- approved -> in_progress
    if old.status = 'approved' then
      if new.status <> 'in_progress' then
        raise exception 'Mechanic may only move job from approved to in_progress';
      end if;
      if new.quote_amount <> old.quote_amount then
        raise exception 'Mechanic cannot modify quote amount after approval';
      end if;
      if new.garage_id <> old.garage_id
         or new.customer_id <> old.customer_id
         or new.vehicle <> old.vehicle then
        raise exception 'Mechanic cannot modify other fields after approval';
      end if;
      return new;
    end if;

    -- in_progress -> done
    if old.status = 'in_progress' then
      if new.status <> 'done' then
        raise exception 'Mechanic may only move job from in_progress to done';
      end if;
      if new.quote_amount <> old.quote_amount then
        raise exception 'Mechanic cannot modify quote amount after approval';
      end if;
      if new.garage_id <> old.garage_id
         or new.customer_id <> old.customer_id
         or new.vehicle <> old.vehicle then
        raise exception 'Mechanic cannot modify other fields after approval';
      end if;
      return new;
    end if;

    raise exception 'Invalid status transition for mechanic';
  end if;

  -- If we reach here, the user is neither the customer nor a mechanic of the garage
  raise exception 'Not authorized to modify this job';
end;
$$;

-- Trigger to enforce column immutability and status flow
create trigger jobs_before_update
before update on public.jobs
for each row
execute function public.validate_job_status_transition();

-- -----------------------------------------------------------------
-- Policies
-- -----------------------------------------------------------------

-- Garages: any signed‑in user can read
create policy "garages_select_authenticated"
on public.garages
for select
using (auth.role() = 'authenticated');

-- Mechanics table: only service_role can read (app never queries it directly)
create policy "mechanics_select_service_role"
on public.mechanics
for select
using (auth.role() = 'service_role');

-- Jobs: SELECT – customers see own jobs, mechanics see jobs of their garage
create policy "jobs_select_customer_or_mechanic"
on public.jobs
for select
using (
  auth.role() = 'authenticated' and
  (customer_id = auth.uid() or public.is_mechanic(garage_id, auth.uid()))
);

-- Jobs: INSERT – only mechanics of the target garage, status must be quoted
create policy "jobs_insert_mechanic"
on public.jobs
for insert
with check (
  auth.role() = 'authenticated' and
  public.is_mechanic(garage_id, auth.uid()) and
  (coalesce(new.status, 'quoted') = 'quoted')
);

-- Jobs: UPDATE – mechanics can update (trigger enforces allowed changes)
create policy "jobs_update_mechanic"
on public.jobs
for update
using (
  auth.role() = 'authenticated' and
  public.is_mechanic(garage_id, auth.uid())
)
with check (true);  -- all column checks are done in trigger

-- Jobs: UPDATE – customers can approve quoted jobs (trigger enforces)
create policy "jobs_update_customer_approve"
on public.jobs
for update
using (
  auth.role() = 'authenticated' and
  customer_id = auth.uid()
)
with check (true);  -- trigger validates the exact change

-- No DELETE policies – deletions are prohibited for all roles except service_role

-- -----------------------------------------------------------------
-- Grants (optional, to make SELECT/INSERT/UPDATE reachable via policies)
-- -----------------------------------------------------------------
grant select on public.garages to authenticated, anon;
grant select, insert, update on public.jobs to authenticated, anon;
grant select on public.mechanics to authenticated, anon;  -- only for internal checks

-- Service role already bypasses RLS, no extra grants needed.
