alter table public.memberships enable row level security;
alter table public.bookings enable row level security;

-- Revoke default privileges from PUBLIC and grant to authenticated role
revoke all on public.desks from public;
grant select on public.desks to authenticated;

revoke all on public.memberships from public;
grant select on public.memberships to authenticated;

revoke all on public.bookings from public;
grant select, insert, delete on public.bookings to authenticated;

-- Helper function to enforce booking constraints
create or replace function public.can_book(p_user_id uuid, p_desk_id bigint, p_day date)
returns boolean
language plpgsql
security definer
as $$
declare
    v_tier          text;
    v_valid_until   date;
    v_zone          text;
    v_upcoming_cnt  int;
begin
    -- membership must exist
    select tier, valid_until into v_tier, v_valid_until
    from public.memberships
    where user_id = p_user_id;

    if not found then
        return false;
    end if;

    -- day must be today or future and within membership validity
    if p_day < current_date then
        return false;
    end if;
    if p_day > v_valid_until then
        return false;
    end if;

    -- desk must exist and premium desks require premium tier
    select zone into v_zone
    from public.desks
    where id = p_desk_id;

    if not found then
        return false;
    end if;

    if v_zone = 'premium' and v_tier <> 'premium' then
        return false;
    end if;

    -- member may hold at most 3 upcoming bookings (including the new one)
    select count(*) into v_upcoming_cnt
    from public.bookings
    where user_id = p_user_id
      and day >= current_date;

    if v_upcoming_cnt >= 3 then
        return false;
    end if;

    return true;
end;
$$;

-- Policies for desks
create policy "desks_select"
    on public.desks
    for select
    to authenticated
    using (true);

-- Policies for memberships
create policy "memberships_select_own"
    on public.memberships
    for select
    to authenticated
    using (user_id = auth.uid());

-- Policies for bookings
create policy "bookings_select_all"
    on public.bookings
    for select
    to authenticated
    using (true);

create policy "bookings_insert"
    on public.bookings
    for insert
    to authenticated
    with check (
        user_id = auth.uid()
        and can_book(auth.uid(), desk_id, day)
    );

create policy "bookings_delete_own_upcoming"
    on public.bookings
    for delete
    to authenticated
    using (
        user_id = auth.uid()
        and day >= current_date
    );
