-- Enable Row Level Security
alter table public.desks enable row level security;
alter table public.memberships enable row level security;
alter table public.bookings enable row level security;

-- -------------------------------------------------
-- Desks: anyone signed‑in can read all desks
create policy desks_select_auth
  on public.desks
  for select
  using (auth.role() = 'authenticated');

-- No writes allowed on desks for app users
create policy desks_no_write
  on public.desks
  for insert with check (false);
create policy desks_no_update
  on public.desks
  for update using (false);
create policy desks_no_delete
  on public.desks
  for delete using (false);

-- -------------------------------------------------
-- Memberships: members can read only their own row
create policy memberships_select_own
  on public.memberships
  for select
  using (user_id = auth.uid());

-- No writes allowed on memberships for app users
create policy memberships_no_write
  on public.memberships
  for insert with check (false);
create policy memberships_no_update
  on public.memberships
  for update using (false);
create policy memberships_no_delete
  on public.memberships
  for delete using (false);

-- -------------------------------------------------
-- Bookings: signed‑in users can read all bookings
create policy bookings_select_auth
  on public.bookings
  for select
  using (auth.role() = 'authenticated');

-- Insert (book) policy
create policy bookings_insert_allowed
  on public.bookings
  for insert
  with check (
    -- must book as yourself
    user_id = auth.uid()
    -- date must be today or future
    and day >= current_date
    -- cannot exceed membership validity
    and day <= (select valid_until from public.memberships m where m.user_id = auth.uid())
    -- premium desk restriction
    and (
          (select zone from public.desks d where d.id = desk_id) = 'standard'
          or (
                (select zone from public.desks d where d.id = desk_id) = 'premium'
                and (select tier from public.memberships m where m.user_id = auth.uid()) = 'premium'
              )
        )
    -- max 3 upcoming bookings (today or later)
    and (
          (select count(*) from public.bookings b
           where b.user_id = auth.uid()
             and b.day >= current_date) < 3
        )
  );

-- Delete (cancel) policy
create policy bookings_delete_own_upcoming
  on public.bookings
  for delete
  using (
    auth.role() = 'authenticated'
    and user_id = auth.uid()
    and day >= current_date
  );

-- No updates allowed on bookings (they are immutable)
create policy bookings_no_update
  on public.bookings
  for update using (false);

-- -------------------------------------------------
-- Grant privileges to the authenticated role (RLS will filter rows)
grant select on public.desks to authenticated;
grant select on public.bookings to authenticated;
grant insert, delete on public.bookings to authenticated;
grant select on public.memberships to authenticated;

-- Revoke any default privileges from anon (they get none)
revoke all on public.desks from anon;
revoke all on public.bookings from anon;
revoke all on public.memberships from anon;
