-- devices: employees see their own devices; admins see all devices in their orgs
create policy "employees can view assigned devices"
  on public.devices
  for select
  using (assigned_to = auth.uid());

create policy "org admins can view all org devices"
  on public.devices
  for select
  using (public.is_org_admin(org_id));

-- device_commands: read access for employees (own device) and org admins (org devices)
create policy "employees and admins can view device commands"
  on public.device_commands
  for select
  using (
    exists (
      select 1
      from public.devices d
      where d.id = device_commands.device_id
        and (
          d.assigned_to = auth.uid()
          or public.is_org_admin(d.org_id)
        )
    )
  );

-- device_commands: admins can insert any command for devices in their orgs
create policy "org admins can insert any command"
  on public.device_commands
  for insert
  with check (
    public.is_org_admin(
      (select org_id from public.devices where id = NEW.device_id)
    )
    and NEW.issued_by = auth.uid()
  );

-- device_commands: employees can insert only locate/lock for devices assigned to them
create policy "employees can insert limited commands"
  on public.device_commands
  for insert
  with check (
    exists (
      select 1
      from public.devices d
      where d.id = NEW.device_id
        and d.assigned_to = auth.uid()
    )
    and NEW.command in ('locate','lock')
    and NEW.issued_by = auth.uid()
  );

-- Disallow updates and deletes on devices, device_commands, org_admins for all non‑service_role users
-- (no UPDATE/DELETE policies means they are denied by default; service_role bypasses RLS)

-- Optional: grant SELECT to authenticated role (writes are controlled by policies)
grant select on public.devices to authenticated;
grant select on public.device_commands to authenticated;
