  on public.household_members
  for select
  using (public.is_member_of_household(auth.uid(), household_id));

-- POLICY: shopping_items – members can view items of their households
create policy "members can view shopping items"
  on public.shopping_items
  for select
  using (public.is_member_of_household(auth.uid(), household_id));

-- POLICY: shopping_items – members can insert new items for their households
create policy "members can insert shopping items"
  on public.shopping_items
  for insert
  with check (
    public.is_member_of_household(auth.uid(), household_id)
    and added_by = auth.uid()
    and claimed_by is null
    and is_bought = false
  );

-- POLICY: shopping_items – members can attempt updates on items of their households
create policy "members can update shopping items"
  on public.shopping_items
  for update
  using (public.is_member_of_household(auth.uid(), household_id));

-- POLICY: shopping_items – members can delete their own un‑bought items
create policy "members can delete own unbought items"
  on public.shopping_items
  for delete
  using (
    public.is_member_of_household(auth.uid(), household_id)
    and added_by = auth.uid()
    and is_bought = false
  );

-- Trigger function that enforces claim / unclaim / buy / delete rules
create or replace function public.enforce_shopping_items_rules()
returns trigger
language plpgsql
as $$
begin
  -- Ensure the caller is a member of the household (defence in depth)
  if not public.is_member_of_household(auth.uid(), NEW.household_id) then
    raise exception 'User % is not a member of household %', auth.uid(), NEW.household_id;
  end if;

  if TG_OP = 'UPDATE' then
    -- Immutable columns
    if NEW.id        is distinct from OLD.id
       or NEW.household_id is distinct from OLD.household_id
       or NEW.added_by is distinct from OLD.added_by then
      raise exception 'household_id, added_by, and id cannot be changed';
    end if;

    -- CLAIM / UNCLAIM
    if NEW.claimed_by is distinct from OLD.claimed_by then
      if OLD.claimed_by is null and NEW.claimed_by = auth.uid() then
        -- claim allowed – no other column may change
        if NEW.is_bought is distinct from OLD.is_bought
           or NEW.name     is distinct from OLD.name then
          raise exception 'Only claimed_by may change when claiming an item';
        end if;
      elsif OLD.claimed_by = auth.uid() and NEW.claimed_by is null then
        -- unclaim allowed – no other column may change
        if NEW.is_bought is distinct from OLD.is_bought
           or NEW.name     is distinct from OLD.name then
          raise exception 'Only claimed_by may change when un‑claiming an item';
        end if;
      else
        raise exception 'Invalid claim/unclaim transition';
      end if;

    -- MARK AS BOUGHT
    elsif NEW.is_bought is distinct from OLD.is_bought then
      if NEW.is_bought = true
         and OLD.is_bought = false
         and OLD.claimed_by = auth.uid() then
        -- only is_bought may change
        if NEW.claimed_by is distinct from OLD.claimed_by
           or NEW.name     is distinct from OLD.name then
          raise exception 'Only is_bought may change when marking bought';
        end if;
      else
        raise exception 'Invalid is_bought transition';
      end if;

    else
      raise exception 'No permitted column changes in this update';
    end if;

    return NEW;

  elsif TG_OP = 'DELETE' then
    if OLD.added_by = auth.uid() and OLD.is_bought = false then
      return OLD;
    else
      raise exception 'Only the creator can delete a non‑bought item';
    end if;
  end if;

  return NULL; -- unreachable
end;
$$;

-- Attach trigger to enforce rules before UPDATE or DELETE
create trigger enforce_shopping_items_rules
before update or delete on public.shopping_items
for each row execute function public.enforce_shopping_items_rules();

-- Grants for authenticated role (service_role bypasses RLS automatically)
grant select, insert, update, delete on public.household_members to authenticated;
grant select, insert, update, delete on public.shopping_items to authenticated;
