-- Enable Row Level Security
alter table public.referral_codes enable row level security;
alter table public.referrals enable row level security;
alter table public.credits enable row level security;

-- SELECT policies (R1)
create policy "own referral code" on public.referral_codes
  for select using (auth.uid() = user_id);

create policy "own referrals (as referrer or referee)" on public.referrals
  for select using (auth.uid() = referrer_id or auth.uid() = referee_id);

create policy "own credits" on public.credits
  for select using (auth.uid() = user_id);

-- No INSERT/UPDATE/DELETE policies for authenticated users (R2) – they are denied by default.

-- Secure function to redeem a referral code (R3, R4)
create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
as $$
declare
    v_owner uuid;
    v_referral_id bigint;
    v_owner_referral_cnt int;
begin
    -- run with service_role to bypass RLS
    set local role = 'service_role';

    -- 1. must be authenticated
    if auth.uid() is null then
        raise exception 'Unauthenticated user';
    end if;

    -- 2. fetch code owner
    select user_id into v_owner
    from public.referral_codes
    where code = p_code
    limit 1;

    if v_owner is null then
        raise exception 'Referral code not found';
    end if;

    -- 3. cannot redeem own code
    if v_owner = auth.uid() then
        raise exception 'Cannot redeem own referral code';
    end if;

    -- 4. caller must not have already redeemed a code
    if exists (select 1 from public.referrals where referee_id = auth.uid()) then
        raise exception 'User has already redeemed a referral code';
    end if;

    -- 5. code owner must have fewer than 5 referrals
    select count(*) into v_owner_referral_cnt
    from public.referrals
    where referrer_id = v_owner;

    if v_owner_referral_cnt >= 5 then
        raise exception 'Referral code owner has reached the maximum number of referrals';
    end if;

    -- 6. record the referral
    insert into public.referrals (referrer_id, referee_id)
    values (v_owner, auth.uid())
    returning id into v_referral_id;

    -- 7. grant credits to both parties
    insert into public.credits (user_id, amount, reason)
    values
        (v_owner, 100, 'referral_bonus'),
        (auth.uid(), 100, 'referral_bonus');

    return v_referral_id;
end;
$$;

-- Grant execute to authenticated users, deny to anon (R5)
grant execute on function public.redeem_referral(text) to authenticated;
revoke execute on function public.redeem_referral(text) from anon;
