-- Audit trigger on records
-- ==========================
create or replace function public.log_record_audit()
returns trigger
language plpgsql
security definer
as $$
begin
    if TG_OP = 'INSERT' then
        insert into public.audit_log (record_id, action, actor)
        values (NEW.id, 'insert', auth.uid());
    elsif TG_OP = 'UPDATE' then
        insert into public.audit_log (record_id, action, actor)
        values (NEW.id, 'update', auth.uid());
    end if;
    return NEW;
end;
$$;

create trigger trg_log_record_audit
after insert or update on public.records
for each row execute function public.log_record_audit();

