returns void
language plpgsql
security definer
as $$
declare
    v_org_id    bigint;
    v_deleted_at timestamptz;
    v_is_admin boolean;
begin
    -- lock the target row
    select org_id, deleted_at
    into   v_org_id, v_deleted_at
    from   public.records
    where  id = p_record_id
    for update;

    if v_deleted_at is null then
        raise exception 'Record % is not deleted', p_record_id;
    end if;

    if now() - v_deleted_at > interval '30 days' then
        raise exception 'Record % was deleted more than 30 days ago', p_record_id;
    end if;

    select exists (
        select 1
        from   public.org_members om
        where  om.org_id = v_org_id
          and  om.user_id = auth.uid()
          and  om.role = 'admin'
    ) into v_is_admin;

    if not v_is_admin then
        raise exception 'User % is not an admin of organization %', auth.uid(), v_org_id;
    end if;

    update public.records
    set    deleted_at = null
    where  id = p_record_id;
end;
$$;

