    select 1
    from public.org_members
    where org_id = p_org
      and user_id = p_user
      and role = 'admin'
  );
$$;

create or replace function public.is_org_member(p_user uuid, p_org bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members
    where org_id = p_org
      and user_id = p_user
  );
$$;

-- Policies for org_members
create policy "members can view own membership"
  on public.org_members
  for select
  using (user_id = auth.uid() or public.is_org_admin(auth.uid(), org_id));

create policy "admins can manage memberships"
  on public.org_members
  for all
  using (public.is_org_admin(auth.uid(), org_id))
  with check (public.is_org_admin(auth.uid(), org_id));

-- Policies for records
create policy "members can select accessible records"
  on public.records
  for select
  using (
    (deleted_at IS NULL and public.is_org_member(auth.uid(), org_id))
    or (deleted_at IS NOT NULL and public.is_org_admin(auth.uid(), org_id))
  );

create policy "members can insert records in their org"
  on public.records
  for insert
  with check (public.is_org_member(auth.uid(), org_id));

create policy "members can update non‑deleted records"
  on public.records
  for update
  using (
    public.is_org_member(auth.uid(), org_id)
    and deleted_at IS NULL
  )
  with check (
    public.is_org_member(auth.uid(), org_id)
    and NEW.deleted_at IS NULL
  );

create policy "admins can delete (set deleted_at) records"
  on public.records
  for update
  using (
    public.is_org_admin(auth.uid(), org_id)
    and NEW.deleted_at IS NOT NULL
  )
  with check (
    public.is_org_admin(auth.uid(), org_id)
    and NEW.deleted_at IS NOT NULL
  );

-- Policies for audit_log
create policy "admins can read audit logs of their org"
  on public.audit_log
  for select
  using (
    public.is_org_admin(
      auth.uid(),
      (select org_id from public.records where id = audit_log.record_id)
    )
  );

-- No write policies on audit_log (writes are denied by default)

-- Trigger to write audit logs on record changes
create or replace function public.record_audit_trigger()
returns trigger
language plpgsql
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (
    NEW.id,
    case when TG_OP = 'INSERT' then 'insert' else 'update' end,
    auth.uid()
  );
  return NEW;
end;
$$;

create trigger trg_record_audit
after insert or update on public.records
for each row
execute function public.record_audit_trigger();

