returns void
language plpgsql
security definer
as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
begin
  -- fetch org and deletion timestamp
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id
  for update;

  if not found then
    raise exception 'Record % does not exist', p_record_id;
  end if;

  if not public.is_org_admin(auth.uid(), v_org_id) then
    raise exception 'Only admins of the organization can restore records';
  end if;

  if v_deleted_at is null then
    raise exception 'Record % is not deleted', p_record_id;
  end if;

  if now() - v_deleted_at > interval '30 days' then
    raise exception 'Record % was deleted more than 30 days ago', p_record_id;
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;

-- Grants
grant execute on function public.restore_record(bigint) to authenticated;
grant usage on schema public to authenticated;
