      join public.org_members om on om.org_id = r.org_id
      where r.id = audit_log.record_id
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

-- Helper function: audit trigger
create function public.record_audit_trigger()
returns trigger
language plpgsql
security definer
as $$
begin
  if TG_OP = 'INSERT' then
    insert into public.audit_log (record_id, action, actor)
    values (NEW.id, 'insert', auth.uid());
    return NEW;
  elsif TG_OP = 'UPDATE' then
    insert into public.audit_log (record_id, action, actor)
    values (NEW.id, 'update', auth.uid());
    return NEW;
  else
    return NULL;
  end if;
end;
$$;

-- Trigger for audit logging
create trigger record_audit_trigger
after insert or update on public.records
for each row execute function public.record_audit_trigger();

-- RPC: restore_record
create function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
as $$
declare
  v_org_id       bigint;
  v_deleted_at   timestamptz;
  v_is_admin     boolean;
begin
  select org_id, deleted_at
    into v_org_id, v_deleted_at
    from public.records
    where id = p_record_id
    for update;

  if not found then
    raise exception 'Record not found';
  end if;

  select exists (
    select 1
    from public.org_members
    where org_id = v_org_id
      and user_id = auth.uid()
      and role = 'admin'
  ) into v_is_admin;

  if not v_is_admin then
    raise exception 'Not authorized';
  end if;

  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  if v_deleted_at < now() - interval '30 days' then
    raise exception 'Deletion period exceeded';
  end if;

  update public.records
    set deleted_at = null
    where id = p_record_id;
end;
$$;

-- Grants
grant select on public.org_members to authenticated;
grant select, insert, update on public.records to authenticated;
grant select on public.audit_log to authenticated;
grant execute on function public.restore_record(bigint) to authenticated;

revoke insert, update, delete on public.audit_log from authenticated;
