```sql
-- Enable Row Level Security
alter table public.proposals enable row level security;
alter table public.reviews   enable row level security;
alter table public.reviewers enable row level security;

-- Helper function to check reviewer status
create or replace function public.is_reviewer(p_uid uuid)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.reviewers where user_id = p_uid);
$$;

-- -------------------------------------------------
-- proposals policies
-- -------------------------------------------------
-- R1: Speakers see own proposals; reviewers see all
create policy "proposals_select_own_or_all"
  on public.proposals
  for select
  using (
    auth.uid() = speaker_id
    or public.is_reviewer(auth.uid())
  );

-- R2: Authenticated users can insert their own proposals (status forced to 'submitted')
create policy "proposals_insert_self"
  on public.proposals
  for insert
  with check (auth.uid() is not null);

-- R2: Speakers can edit their own proposals while still 'submitted'
create policy "proposals_update_own_while_submitted"
  on public.proposals
  for update
  using (
    auth.uid() = speaker_id
    and status = 'submitted'
  )
  with check (
    auth.uid() = speaker_id
    and status = 'submitted'
  );

-- -------------------------------------------------
-- reviews policies
-- -------------------------------------------------
-- R4: Reviewers see only their own reviews; speakers see reviews of their proposals after decision
create policy "reviews_select_own_or_speaker_after_decision"
  on public.reviews
  for select
  using (
    auth.uid() = reviewer_id
    or exists (
      select 1
      from public.proposals p
      where p.id = proposal_id
        and p.speaker_id = auth.uid()
        and p.status in ('accepted','rejected')
    )
  );

-- R3: Reviewers can insert a review for an undecided proposal they don't own
create policy "reviews_insert_allowed"
  on public.reviews
  for insert
  with check (
    public.is_reviewer(auth.uid())
    and (select status from public.proposals p where p.id = proposal_id) = 'submitted'
    and (select speaker_id from public.proposals p where p.id = proposal_id) <> auth.uid()
  );

-- R3: Reviewers can update their own review while proposal is still undecided
create policy "reviews_update_own_while_submitted"
  on public.reviews
  for update
  using (
    auth.uid() = reviewer_id
    and (select status from public.proposals p where p.id = proposal_id) = 'submitted'
  )
  with check (
    auth.uid() = reviewer_id
  );

-- -------------------------------------------------
-- reviewers policies
-- -------------------------------------------------
-- R5: Users can see whether they themselves are a reviewer (their own row)
create policy "reviewers_select_own"
  on public.reviewers
  for select
  using (user_id = auth.uid());

-- No insert/update/delete policies: only service_role (bypasses RLS) can modify

-- -------------------------------------------------
-- Triggers to enforce immutable fields & defaults
-- -------------------------------------------------
-- proposals: force speaker_id = auth.uid() and status = 'submitted' on insert
create or replace function public.proposals_before_insert()
returns trigger
language plpgsql
as $$
begin
  new.speaker_id := auth.uid();
  new.status := 'submitted';
  return new;
end;
$$;

create trigger trg_proposals_before_insert
before insert on public.proposals
for each row execute function public.proposals_before_insert();

-- proposals: prevent status change by non‑service_role users
create or replace function public.proposals_before_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() <> 'service_role' and new.status <> old.status then
    raise exception 'Only service_role may change proposal status';
  end if;
  -- also protect speaker_id from being altered by anyone
  if new.speaker_id <> old.speaker_id then
    raise exception 'speaker_id is immutable';
  end if;
  return new;
end;
$$;

create trigger trg_proposals_before_update
before update on public.proposals
for each row execute function public.proposals_before_update();

-- reviews: force reviewer_id = auth.uid() on insert
create or replace function public.reviews_before_insert()
returns trigger
language plpgsql
as $$
begin
  new.reviewer_id := auth.uid();
  return new;
end;
$$;

create trigger trg_reviews_before_insert
before insert on public.reviews
for each row execute function public.reviews_before_insert();

-- reviews: protect reviewer_id from being altered on update
create or replace function public.reviews_before_update()
returns trigger
language plpgsql
as $$
begin
  if new.reviewer_id <> old.reviewer_id then
    raise exception 'reviewer_id is immutable';
  end if;
  return new;
end;
$$;

create trigger trg_reviews_before_update
before update on public.reviews
for each row execute function public.reviews_before_update();

-- -------------------------------------------------
-- Grant minimal access (optional, can be omitted if defaults suffice)
-- -------------------------------------------------
grant select, insert, update on public.proposals to authenticated;
grant select, insert, update on public.reviews   to authenticated;
grant select on public.reviewers                to authenticated;
