         and c.instructor_id = auth.uid()
     ))
  );

-- Trigger to enforce allowed status transitions and prevent column tampering
create or replace function public.spot_update_check()
returns trigger
language plpgsql
as $$
begin
  -- Prevent changes to class_id or user_id
  if NEW.class_id <> OLD.class_id then
    raise exception 'class_id cannot be modified';
  end if;
  if NEW.user_id <> OLD.user_id then
    raise exception 'user_id cannot be modified';
  end if;

  -- Allow only waitlisted -> enrolled when capacity permits; otherwise no status change
  if NEW.status <> OLD.status then
    if OLD.status = 'waitlisted' and NEW.status = 'enrolled' then
      if not public.can_enroll(NEW.class_id) then
        raise exception 'Class is full, cannot change status to enrolled';
      end if;
    else
      raise exception 'Invalid status transition';
    end if;
  end if;

  return NEW;
end;
$$;

create trigger spot_update_check
before update on public.class_spots
for each row execute function public.spot_update_check();

