-- Trigger to enforce insert rules on class_spots
create or replace function public.tg_class_spots_before_insert()
returns trigger
language plpgsql
as $$
begin
  -- enforce insertion as self
  if new.user_id is null then
    new.user_id := auth.uid();
  end if;

  if new.user_id <> auth.uid() then
    raise exception 'You can only create a spot for yourself';
  end if;

  -- enforce capacity rule for enrolled status
  if new.status = 'enrolled' and not public.can_enroll(new.class_id) then
    raise exception 'Class is full – you must join as waitlisted';
  end if;

  return new;
end;
$$;

