-- -------------------------------------------------
-- Helper functions
-- -------------------------------------------------
create or replace function public.can_insert_spot(p_class_id bigint, p_user_id uuid, p_status text)
returns boolean
language plpgsql
stable
as $$
declare
    enrolled_cnt int;
    cap int;
begin
    if p_user_id <> auth.uid() then
        return false;
    end if;

    select capacity into cap
    from public.classes
    where id = p_class_id;

    if cap is null then
        return false;
    end if;

    select count(*) into enrolled_cnt
