-- Helper function to check enrollment capacity
create or replace function public.can_enroll(p_class_id bigint)
returns boolean
language sql
stable
as $$
  select
    (select capacity from public.classes where id = p_class_id) >
    (select count(*) from public.class_spots where class_id = p_class_id and status = 'enrolled');
$$;

-- Trigger to enforce insert rules on class_spots
create or replace function public.tg_class_spots_before_insert()
returns trigger
language plpgsql
as $$
begin
  -- enforce insertion as self
  if new.user_id is null then
    new.user_id := auth.uid();
  end if;

  if new.user_id <> auth.uid() then
    raise exception 'You can only create a spot for yourself';
  end if;

  -- enforce capacity rule for enrolled status
  if new.status = 'enrolled' and not public.can_enroll(new.class_id) then
    raise exception 'Class is full – you must join as waitlisted';
  end if;

  return new;
end;
$$;

create trigger trg_class_spots_before_insert
before insert on public.class_spots
for each row execute function public.tg_class_spots_before_insert();

-- Trigger to enforce update rules on class_spots
create or replace function public.tg_class_spots_before_update()
returns trigger
language plpgsql
as $$
begin
  -- only the owner may update
  if old.user_id <> auth.uid() then
    raise exception 'You can only update your own spot';
  end if;

  -- class_id and user_id are immutable
  if new.class_id <> old.class_id or new.user_id <> old.user_id then
    raise exception 'class_id and user_id cannot be changed';
  end if;

  -- status transition rules
  if new.status <> old.status then
    if new.status = 'enrolled' then
      if not public.can_enroll(new.class_id) then
        raise exception 'No room to move to enrolled status';
      end if;
    elsif new.status <> 'waitlisted' then
      raise exception 'Invalid status value';
    end if;
  end if;

  return new;
end;
$$;

create trigger trg_class_spots_before_update
before update on public.class_spots
for each row execute function public.tg_class_spots_before_update();

