-- Enable RLS
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- Helper function for permit insertion constraints
create or replace function public.can_insert_permit(p_unit_id bigint, p_valid_until date)
returns boolean
language plpgsql
stable
as $$
declare
    resident_exists boolean;
    active_cnt int;
begin
    -- Must be a resident of the unit
    select exists (
        select 1
        from public.residents r
        where r.unit_id = p_unit_id
          and r.user_id = auth.uid()
    ) into resident_exists;
    if not resident_exists then
        return false;
    end if;

    -- No more than 2 active permits for the unit
    select count(*) into active_cnt
    from public.permits per
    where per.unit_id = p_unit_id
      and per.revoked = false
      and per.valid_until >= current_date;
    if active_cnt >= 2 then
        return false;
    end if;

    -- Validity period limited to 365 days from today
    if p_valid_until > (current_date + interval '365 days') then
        return false;
    end if;

    return true;
end;
$$;

-- ----------------------------------------------------------------------
-- residents table policies
-- ----------------------------------------------------------------------
-- Residents can see their own rows; HOA admins can see all rows
create policy "residents select own or admin"
    on public.residents
    for select
    using (
        auth.uid() = user_id
        or auth.uid() in (select user_id from public.hoa_admins)
        or auth.role() = 'service_role'
    );

-- Service role full access (covers insert/update/delete)
create policy "residents service_role full"
    on public.residents
    for all
    using (auth.role() = 'service_role')
    with check (auth.role() = 'service_role');

-- ----------------------------------------------------------------------
-- hoa_admins table policies
-- ----------------------------------------------------------------------
-- Only service_role may read/modify; app users cannot
create policy "hoa_admins service_role full"
    on public.hoa_admins
    for all
    using (auth.role() = 'service_role')
    with check (auth.role() = 'service_role');

-- ----------------------------------------------------------------------
-- permits table policies
-- ----------------------------------------------------------------------
-- Select: residents see permits of their unit; admins see all
create policy "permits select resident or admin"
    on public.permits
    for select
    using (
        auth.uid() in (select r.user_id from public.residents r where r.unit_id = permits.unit_id)
        or auth.uid() in (select user_id from public.hoa_admins)
        or auth.role() = 'service_role'
    );

-- Insert: residents can add permits for their unit respecting limits
create policy "permits insert resident"
    on public.permits
    for insert
    with check (
        auth.role() = 'service_role'                                   -- service_role bypass
        or (
            new.revoked = false
            and public.can_insert_permit(new.unit_id, new.valid_until)
        )
    );

-- Update: residents may only change the plate of permits belonging to their unit
create policy "permits update resident plate"
    on public.permits
    for update
    using (
        auth.uid() in (select r.user_id from public.residents r where r.unit_id = permits.unit_id)
        or auth.role() = 'service_role'
    )
    with check (
        auth.role() = 'service_role'
        or (
            new.unit_id = old.unit_id
            and new.revoked = old.revoked
            and new.valid_until = old.valid_until
        )
    );

-- Update: HOA admins may set revoked = true (cannot un‑revoke)
create policy "permits update admin revoke"
    on public.permits
    for update
    using (
        auth.uid() in (select user_id from public.hoa_admins)
        or auth.role() = 'service_role'
    )
    with check (
        auth.role() = 'service_role'
        or (
            new.revoked = true
            and old.revoked = false
            and new.unit_id = old.unit_id
            and new.valid_until = old.valid_until
            and new.plate = old.plate
        )
    );

-- Service role full access for permits (covers any missing actions)
create policy "permits service_role full"
    on public.permits
    for all
    using (auth.role() = 'service_role')
    with check (auth.role() = 'service_role');
