alter table public.medical_records      enable row level security;
alter table public.break_glass_grants  enable row level security;
alter table public.care_team           enable row level security;
alter table public.patients            enable row level security;
alter table public.clinicians          enable row level security;
alter table public.auditors            enable row level security;

-- medical_records: clinicians can read records of their patients or where they have an unexpired break‑glass grant
create policy medical_records_select_clinician on public.medical_records
  for select
  using (
    exists (
      select 1
      from   public.care_team ct
      where  ct.patient_id = medical_records.patient_id
        and  ct.clinician_id = auth.uid()
    )
    or
    exists (
      select 1
      from   public.break_glass_grants bg
      where  bg.patient_id = medical_records.patient_id
        and  bg.clinician_id = auth.uid()
        and  bg.expires_at > now()
    )
  );

-- break_glass_grants: clinicians see only their own grants; auditors see all grants
create policy break_glass_grants_select_clinician on public.break_glass_grants
  for select
  using (clinician_id = auth.uid());

create policy break_glass_grants_select_auditor on public.break_glass_grants
  for select
  using (exists (select 1 from public.auditors a where a.user_id = auth.uid()));

-- care_team: clinicians can see rows that belong to them
create policy care_team_select_clinician on public.care_team
  for select
  using (clinician_id = auth.uid());

-- patients: clinicians can read patient rows they are allowed to see (via care team or break‑glass)
create policy patients_select_clinician on public.patients
  for select
  using (
    exists (
      select 1
      from   public.care_team ct
      where  ct.patient_id = patients.id
        and  ct.clinician_id = auth.uid()
    )
    or
    exists (
      select 1
      from   public.break_glass_grants bg
      where  bg.patient_id = patients.id
        and  bg.clinician_id = auth.uid()
        and  bg.expires_at > now()
    )
  );

-- clinicians table: clinicians can read their own row
create policy clinicians_select_self on public.clinicians
  for select
  using (user_id = auth.uid());

-- auditors table: auditors can read their own row
create policy auditors_select_self on public.auditors
  for select
  using (user_id = auth.uid());

-- ----------------------------------------------------------------------
-- Helper function: break_glass
-- Creates a one‑hour grant for the calling clinician after validation.
-- ----------------------------------------------------------------------
create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
as $$
declare
    v_reason   text;
    v_expires  timestamptz;
begin
    -- Must be a clinician
    if not exists (select 1 from public.clinicians where user_id = auth.uid()) then
        raise exception 'Only clinicians may invoke break_glass';
    end if;

    -- Patient must exist
    if not exists (select 1 from public.patients where id = p_patient_id) then
        raise exception 'Patient % does not exist', p_patient_id;
    end if;

    -- Reason must be at least 10 non‑space characters
    v_reason := btrim(p_reason);
    if length(v_reason) < 10 then
        raise exception 'Reason must be at least 10 characters';
    end if;

    -- Insert grant and return expiry timestamp
    insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
    values (p_patient_id, auth.uid(), v_reason, now() + interval '1 hour')
    returning expires_at into v_expires;

    return v_expires;
end;
$$;

-- Revoke default public privileges (optional hardening)
revoke all on public.medical_records      from public;
revoke all on public.break_glass_grants  from public;
revoke all on public.care_team           from public;
revoke all on public.patients            from public;
revoke all on public.clinicians          from public;
revoke all on public.auditors            from public;
