returns timestamptz
language plpgsql
security definer
as $$
declare
    v_expires timestamptz;
    v_trimmed text;
begin
    -- Must be a clinician
    if not exists (select 1 from public.clinicians where user_id = auth.uid()) then
        raise exception 'Only clinicians can call break_glass';
