```sql
-- Enable Row Level Security
alter table public.warehouses enable row level security;
alter table public.warehouse_staff enable row level security;
alter table public.stock enable row level security;
alter table public.transfers enable row level security;

-- Policies --------------------------------------------------------------

-- Warehouses: any signed‑in user can read
create policy "warehouses_select_auth"
    on public.warehouses
    for select
    using (auth.role() = 'authenticated');

-- Stock: only staff of the warehouse can read
create policy "stock_select_staff"
    on public.stock
    for select
    using (
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = stock.warehouse_id
              and ws.user_id = auth.uid()
        )
    );

-- Transfers: staff of either source or destination can read
create policy "transfers_select_staff"
    on public.transfers
    for select
    using (
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = transfers.from_warehouse
              and ws.user_id = auth.uid()
        )
        or
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = transfers.to_warehouse
              and ws.user_id = auth.uid()
        )
    );

-- No insert / update / delete policies are created → those actions are denied
-- -------------------------------------------------------------------------

-- Function: transfer_stock ------------------------------------------------
create or replace function public.transfer_stock(
    p_from bigint,
    p_to   bigint,
    p_sku  text,
    p_qty  integer
) returns integer
language plpgsql
security definer
as $$
declare
    v_user   uuid := auth.uid();
    v_src_qty integer;
begin
    -- 1. must be an authenticated user
    if v_user is null then
        raise exception 'unauthenticated';
    end if;

    -- 2. basic argument validation
    if p_qty <= 0 then
        raise exception 'quantity must be positive';
    end if;
    if p_from = p_to then
        raise exception 'source and destination warehouses must differ';
    end if;

    -- 3. warehouses must exist
    if not exists (select 1 from public.warehouses where id = p_from) then
        raise exception 'source warehouse % does not exist', p_from;
    end if;
    if not exists (select 1 from public.warehouses where id = p_to) then
        raise exception 'destination warehouse % does not exist', p_to;
    end if;

    -- 4. caller must be staff of source warehouse
    if not exists (
        select 1
        from public.warehouse_staff ws
        where ws.warehouse_id = p_from
          and ws.user_id = v_user
    ) then
        raise exception 'user % is not staff of source warehouse %', v_user, p_from;
    end if;

    -- 5. lock source stock row
    select qty into v_src_qty
    from public.stock
    where warehouse_id = p_from
      and sku = p_sku
    for update;

    if v_src_qty is null or v_src_qty < p_qty then
        raise exception 'insufficient stock in source warehouse';
    end if;

    -- 6. deduct from source
    update public.stock
    set qty = qty - p_qty
    where warehouse_id = p_from
      and sku = p_sku;

    -- 7. add to destination (upsert)
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty)
    on conflict (warehouse_id, sku) do
        update set qty = public.stock.qty + EXCLUDED.qty;

    -- 8. record the transfer
    insert into public.transfers (
        from_warehouse,
        to_warehouse,
        sku,
        qty,
        moved_by
    ) values (
        p_from,
        p_to,
        p_sku,
        p_qty,
        v_user
    );

    return v_src_qty - p_qty;  -- quantity left at source
end;
$$;

-- Grants -----------------------------------------------------------------
grant select on public.warehouses to authenticated;
grant select on public.stock to authenticated;
grant select on public.transfers to authenticated;

