alter table public.stock enable row level security;
alter table public.transfers enable row level security;

-- ----------------------------------------------------------------
-- Policies
-- ----------------------------------------------------------------

-- R1: All signed‑in users can read the list of warehouses
create policy "authenticated select warehouses"
    on public.warehouses
    for select
    using (auth.role() = 'authenticated');

-- R1: Staff can read stock of their own warehouses
