    on public.stock
    for select
    using (
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = stock.warehouse_id
              and ws.user_id = auth.uid()
        )
    );

-- R1: Staff can read transfers where they are involved (as source or destination)
create policy "staff select transfers"
    on public.transfers
    for select
    using (
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = transfers.from_warehouse
              and ws.user_id = auth.uid()
        )
        or
        exists (
            select 1
            from public.warehouse_staff ws
            where ws.warehouse_id = transfers.to_warehouse
              and ws.user_id = auth.uid()
        )
    );

-- R2: No one (except service_role) may insert/update/delete stock directly
create policy "no write stock"
    on public.stock
    for all
    using (false);

-- R2: No one (except service_role) may insert/update/delete transfers directly
create policy "no write transfers"
    on public.transfers
    for all
    using (false);

-- R5: Anonymous users have no access – no policies granted to role anon
-- (implicitly enforced by the lack of select/execute grants)

-- ----------------------------------------------------------------
-- Helper function: transfer_stock
-- ----------------------------------------------------------------
create or replace function public.transfer_stock(
    p_from bigint,
    p_to   bigint,
    p_sku  text,
    p_qty  integer
) returns integer
language plpgsql
security definer
as $$
declare
    v_source_qty integer;
    v_new_source_qty integer;
begin
    -- R4: caller must be authenticated
    if auth.uid() is null then
        raise exception 'unauthenticated user';
    end if;

    -- R4: quantity must be positive
    if p_qty <= 0 then
        raise exception 'quantity must be positive';
    end if;

    -- R4: source and destination must be different
    if p_from = p_to then
        raise exception 'source and destination warehouses must differ';
    end if;

    -- R4: both warehouses must exist
    if not exists (select 1 from public.warehouses where id = p_from) then
        raise exception 'source warehouse does not exist';
    end if;
    if not exists (select 1 from public.warehouses where id = p_to) then
        raise exception 'destination warehouse does not exist';
    end if;

    -- R4: caller must be staff of source warehouse
    if not exists (
        select 1
        from public.warehouse_staff ws
        where ws.warehouse_id = p_from
          and ws.user_id = auth.uid()
    ) then
        raise exception 'caller is not staff of source warehouse';
    end if;

    -- R4: source must have enough stock
    select qty into v_source_qty
    from public.stock
    where warehouse_id = p_from
      and sku = p_sku
    for update;  -- lock the row

    if v_source_qty is null or v_source_qty < p_qty then
        raise exception 'insufficient stock in source warehouse';
    end if;

    -- Update source stock
    v_new_source_qty := v_source_qty - p_qty;
    update public.stock
    set qty = v_new_source_qty
    where warehouse_id = p_from
      and sku = p_sku;

    -- Upsert destination stock
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty)
    on conflict (warehouse_id, sku) do update
        set qty = public.stock.qty + EXCLUDED.qty;

    -- Record the transfer
    insert into public.transfers (
        from_warehouse,
        to_warehouse,
        sku,
        qty,
        moved_by,
        moved_at
    ) values (
        p_from,
        p_to,
        p_sku,
        p_qty,
        auth.uid(),
        now()
    );

    return v_new_source_qty;
end;
$$;

