language plpgsql
security definer
as $$
declare
    caller_id   uuid := auth.uid();
    caller_role text;
begin
    -- verify caller is member of the org
    select role into caller_role
    from public.org_members
    where org_id = p_org_id and user_id = caller_id;

    if caller_role is null then
        raise exception 'Caller is not a member of the organization';
    end if;

    if caller_role not in ('owner', 'admin') then
        raise exception 'Caller must be owner or admin';
    end if;

    if p_user_id = caller_id then
        raise exception 'Cannot change own role';
    end if;

    if p_role not in ('admin', 'member') then
        raise exception 'Invalid target role';
    end if;

    -- target must belong to the same org
    if not exists (
        select 1
        from public.org_members
        where org_id = p_org_id and user_id = p_user_id
    ) then
        raise exception 'Target user is not a member of the organization';
    end if;

    -- cannot target an owner
    if exists (
        select 1
        from public.org_members
        where org_id = p_org_id and user_id = p_user_id and role = 'owner'
    ) then
        raise exception 'Cannot change role of an owner';
    end if;

    update public.org_members
    set role = p_role
    where org_id = p_org_id and user_id = p_user_id;

    return p_role;
end;
$$;

