    select role into v_caller_role
    from public.org_members
    where org_id = p_org_id and user_id = v_caller_id;

    if v_caller_role is null then
        raise exception 'Caller is not a member of organization %', p_org_id;
    end if;

    if v_caller_role not in ('owner','admin') then
        raise exception 'Caller lacks permission (role=%) to change member roles', v_caller_role;
    end if;

    if v_caller_id = p_user_id then
        raise exception 'Caller cannot change their own role';
    end if;

    -- target must exist and not be an owner
    select role into v_target_role
    from public.org_members
    where org_id = p_org_id and user_id = p_user_id;

    if v_target_role is null then
        raise exception 'Target user % is not a member of organization %', p_user_id, p_org_id;
    end if;

    if v_target_role = 'owner' then
        raise exception 'Cannot change role of an owner';
